let IDIOMA_ATUAL = "pt";

function t(chave, vars){
  let texto = (TRADUCOES[IDIOMA_ATUAL] && TRADUCOES[IDIOMA_ATUAL][chave]) || (TRADUCOES.pt[chave]) || chave;
  if(vars){ Object.entries(vars).forEach(([k,v]) => { texto = texto.replace(`{${k}}`, v); }); }
  return texto;
}

function aplicarIdioma(lang){
  IDIOMA_ATUAL = lang;
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const chave = el.getAttribute("data-i18n");
    if(TRADUCOES[lang] && TRADUCOES[lang][chave]) el.innerHTML = TRADUCOES[lang][chave];
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{
    const chave = el.getAttribute("data-i18n-placeholder");
    if(TRADUCOES[lang] && TRADUCOES[lang][chave]) el.setAttribute("placeholder", TRADUCOES[lang][chave]);
  });
  document.getElementById("idioma-login").value = lang;
  document.getElementById("idioma-app").value = lang;

  // Atualiza título/subtítulo da view atual
  const viewAtiva = document.querySelector(".nav-item.ativo");
  if(viewAtiva) atualizarTopbar(viewAtiva.dataset.view);

  // Re-renderiza conteúdo dinâmico que contém texto traduzido
  if(!document.getElementById("view-dashboard").classList.contains("oculto")) renderizarDashboard();
  if(!document.getElementById("view-alunos").classList.contains("oculto")) renderizarTabelaAlunos();
  if(!document.getElementById("view-matriculas").classList.contains("oculto")) renderizarMatriculas();
  if(!document.getElementById("view-pdv").classList.contains("oculto")) renderizarCaixaDoDia();
  if(document.getElementById("view-novidades") && !document.getElementById("view-novidades").classList.contains("oculto")) renderizarNovidades();
}

function saudacaoPorHorario(){
  const hora = new Date().getHours();
  if(hora >= 5 && hora < 12) return { pt:"Bom dia", en:"Good morning", es:"Buenos días", fimpt:"dia", fimen:"day", fimes:"día", artigopt:"um" };
  if(hora >= 12 && hora < 18) return { pt:"Boa tarde", en:"Good afternoon", es:"Buenas tardes", fimpt:"tarde", fimen:"afternoon", fimes:"tarde", artigopt:"uma" };
  return { pt:"Boa noite", en:"Good evening", es:"Buenas noches", fimpt:"noite", fimen:"evening", fimes:"noche", artigopt:"uma" };
}
function horaFormatada(){
  return new Date().toLocaleTimeString(IDIOMA_ATUAL==='en'?"en-US":(IDIOMA_ATUAL==='es'?"es-ES":"pt-BR"), {hour:"2-digit", minute:"2-digit"});
}
const FRASES_BANNER = [
  { pt:"Grandes conquistas começam com uma boa gestão.", en:"Great achievements begin with good management.", es:"Los grandes logros comienzan con una buena gestión." },
  { pt:"Educação de qualidade transforma o futuro.", en:"Quality education transforms the future.", es:"La educación de calidad transforma el futuro." },
  { pt:"Organização hoje, resultados amanhã.", en:"Organization today, results tomorrow.", es:"Organización hoy, resultados mañana." },
  { pt:"Cada matrícula é um novo começo.", en:"Every enrollment is a new beginning.", es:"Cada matrícula es un nuevo comienzo." },
];
function atualizarBannerDashboard(){
  const elData = document.getElementById("banner-data-extenso");
  const elHora = document.getElementById("banner-hora");
  const elFrase = document.getElementById("banner-frase");
  if(!elData || !elHora) return;
  const locale = IDIOMA_ATUAL==='en' ? "en-US" : (IDIOMA_ATUAL==='es' ? "es-ES" : "pt-BR");
  elData.textContent = new Date().toLocaleDateString(locale, {weekday:"long", day:"2-digit", month:"long", year:"numeric"});
  elHora.textContent = horaFormatada();
  if(elFrase){
    const idx = Math.floor(Date.now() / 60000) % FRASES_BANNER.length;
    const f = FRASES_BANNER[idx];
    elFrase.textContent = `"${f[IDIOMA_ATUAL] || f.pt}"`;
  }
}

function atualizarRelogioTopo(){
  const chip = document.getElementById("chip-hora");
  if(chip) chip.textContent = `🕐 ${horaFormatada()}`;
  atualizarBannerDashboard();
  // Enquanto o dashboard estiver aberto, mantém a saudação e a hora sempre atualizadas
  if(CURRENT_USUARIO && !document.getElementById("view-dashboard").classList.contains("oculto")){
    atualizarTopbar("dashboard");
  }
}

function atualizarTopbar(view){
  if(view === "dashboard" && CURRENT_USUARIO){
    const s = saudacaoPorHorario();
    const primeiroNome = CURRENT_USUARIO.nome.split(" ")[0];
    const saudacao = s[IDIOMA_ATUAL] || s.pt;
    const fimFrase = IDIOMA_ATUAL==='en' ? s.fimen : (IDIOMA_ATUAL==='es' ? s.fimes : s.fimpt);
    const fraseBoasVindas = IDIOMA_ATUAL==='en'
      ? `Welcome to Nexus Tech University. Have a great ${fimFrase}! · ${horaFormatada()}`
      : (IDIOMA_ATUAL==='es'
        ? `Bienvenido(a) a Nexus Tech University. ¡Que tengas una excelente ${fimFrase}! · ${horaFormatada()}`
        : `Bem-vindo(a) ao Nexus Tech University. Tenha ${s.artigopt} excelente ${fimFrase}! · ${horaFormatada()}`);
    document.getElementById("topbar-titulo").textContent = `${saudacao}, ${primeiroNome}! 👋`;
    document.getElementById("topbar-sub").textContent = fraseBoasVindas;
    return;
  }
  document.getElementById("topbar-titulo").textContent = t(`view.${view}.titulo`);
  document.getElementById("topbar-sub").textContent = t(`view.${view}.sub`);
}

