function aleatorio(lista){ return lista[Math.floor(Math.random()*lista.length)]; }
function numeroEntre(min,max){ return Math.floor(Math.random()*(max-min+1))+min; }
function pad(n,len){ return String(n).padStart(len,"0"); }
function moeda(v){ return "R$ " + Number(v).toFixed(2).replace(".",","); }

function gerarCPF(){
  return `${numeroEntre(100,999)}.${numeroEntre(100,999)}.${numeroEntre(100,999)}-${pad(numeroEntre(0,99),2)}`;
}
function gerarTelefone(){
  return `(35) 9${numeroEntre(6000,9999)}-${pad(numeroEntre(0,9999),4)}`;
}
function gerarDataNascimento(idadeMin, idadeMax){
  const hoje = new Date();
  const idade = numeroEntre(idadeMin, idadeMax);
  const ano = hoje.getFullYear() - idade;
  const mes = numeroEntre(0,11);
  const dia = numeroEntre(1,28);
  return new Date(ano, mes, dia);
}
function calcularIdade(dataNasc){
  const hoje = new Date();
  let idade = hoje.getFullYear() - dataNasc.getFullYear();
  const m = hoje.getMonth() - dataNasc.getMonth();
  if(m < 0 || (m === 0 && hoje.getDate() < dataNasc.getDate())) idade--;
  return idade;
}
function formatarData(d){
  if(typeof d === "string") d = new Date(d);
  return `${pad(d.getDate(),2)}/${pad(d.getMonth()+1,2)}/${d.getFullYear()}`;
}
function paraInputDate(d){
  if(typeof d === "string") return d;
  return `${d.getFullYear()}-${pad(d.getMonth()+1,2)}-${pad(d.getDate(),2)}`;
}

// ============ VALIDAÇÃO DE DOCUMENTOS (código + QR Code) ============
// Registro local dos documentos emitidos nesta sessão, para permitir a
// "consulta de validação" (ver função consultarValidacaoDocumento).
let DOCUMENTOS_EMITIDOS = [];

function gerarCodigoValidacao(aluno, tipo){
  const base = `${aluno.id}-${tipo}-${aluno.matricula}-${Date.now()}-${Math.random()}`;
  let hash = 0;
  for(let i=0;i<base.length;i++){ hash = ((hash<<5)-hash) + base.charCodeAt(i); hash |= 0; }
  const parte1 = Math.abs(hash).toString(36).toUpperCase().padStart(6,"0").slice(0,6);
  const parte2 = Date.now().toString(36).toUpperCase().slice(-4);
  return `NEX-${parte1}-${parte2}`;
}

function registrarDocumentoEmitido(aluno, tipo, codigo){
  DOCUMENTOS_EMITIDOS.unshift({
    codigo, alunoId: aluno.id, alunoNome: aluno.nome, tipo,
    emitidoPor: CURRENT_USUARIO ? CURRENT_USUARIO.nome : "—",
    unidade: aluno.unidade || CURRENT_UNIDADE,
    dataHora: new Date().toISOString()
  });
  if(DOCUMENTOS_EMITIDOS.length > 300) DOCUMENTOS_EMITIDOS.length = 300;
}

function svgQRCodeValidacao(texto, tamanhoPx){
  try{
    const qr = qrcode(0, "M");
    qr.addData(texto);
    qr.make();
    const modulos = qr.getModuleCount();
    const cellSize = Math.max(2, Math.floor((tamanhoPx||120) / modulos));
    return qr.createSvgTag({ cellSize, margin: cellSize * 2, scalable: true });
  }catch(e){
    return "";
  }
}

let ULTIMA_MATRICULA = 20250001;
let ULTIMA_RA = 1;

function gerarRA(){
  return String(ULTIMA_RA++).padStart(7,"0");
}

function gerarAlunoFicticio(indice){
  const genero = Math.random() < 0.5 ? "M" : "F";
  const primeiro = genero === "M" ? aleatorio(NOMES_M) : aleatorio(NOMES_F);
  const nome = `${primeiro} ${aleatorio(SOBRENOMES)} ${aleatorio(SOBRENOMES)}`;

  const chavesUnidade = Object.keys(UNIDADES);
  const unidade = chavesUnidade[indice % chavesUnidade.length];
  const infoUnidade = UNIDADES[unidade];

  const categoria = aleatorio(NOMES_CATEGORIAS);
  const infoCategoria = CATEGORIAS[categoria];
  const curso = aleatorio(infoCategoria.cursos);
  const nascimento = gerarDataNascimento(infoCategoria.idadeMin, infoCategoria.idadeMax);
  const idade = calcularIdade(nascimento);
  const menorIdade = idade < 18;

  const hoje = new Date();
  const diasAtras = numeroEntre(0, 720);
  const dataMatricula = new Date(hoje.getTime() - diasAtras*24*60*60*1000);

  const anoTurma = dataMatricula.getFullYear();
  const semestreTurma = dataMatricula.getMonth() < 6 ? 1 : 2;
  const siglaCurso = curso.split(" ").map(p=>p[0]).join("").toUpperCase().slice(0,4);
  const turma = `${siglaCurso}-${anoTurma}.${semestreTurma}`;

  let status = aleatorio(STATUS_LISTA);
  if(diasAtras > 500 && Math.random() < 0.5) status = "Concluído";

  return {
    id: indice + 1,
    matricula: String(ULTIMA_MATRICULA++),
    ra: gerarRA(),
    nome, genero,
    nascimento: paraInputDate(nascimento),
    cpf: gerarCPF(),
    telefone: gerarTelefone(),
    email: `${primeiro.toLowerCase()}.${1000+indice}@aluno.etec.br`,
    endereco: `Rua ${aleatorio(SOBRENOMES)}, ${numeroEntre(10,1800)} - Centro, ${infoUnidade.cidade}/${infoUnidade.uf}`,
    unidade,
    categoria, curso, turma,
    cargaHoraria: infoCategoria.cargaHoraria,
    dataMatricula: paraInputDate(dataMatricula),
    status, menorIdade,
    responsavel: menorIdade ? {
      nome: `${aleatorio(NOMES_F.concat(NOMES_M))} ${aleatorio(SOBRENOMES)} ${aleatorio(SOBRENOMES)}`,
      parentesco: aleatorio(PARENTESCOS),
      cpf: gerarCPF(),
      telefone: gerarTelefone()
    } : null
  };
}

function gerarBaseFicticia(qtd){
  const lista = [];
  for(let i=0;i<qtd;i++) lista.push(gerarAlunoFicticio(i));
  return lista;
}

