/* ---------------------------------------------------------
   2.2 TURMAS — derivadas dos códigos de turma já usados pelos alunos,
   enriquecidas com professor responsável, turno, sala e capacidade.
--------------------------------------------------------- */
const TURNOS = ["Manhã","Tarde","Noite"];
const HORARIOS_TURNO = { "Manhã":"08h às 12h", "Tarde":"13h30 às 17h30", "Noite":"19h às 22h" };
let ULTIMO_ID_TURMA = 1;

function gerarTurmasDosAlunos(){
  const mapa = new Map();
  ALUNOS.forEach(a=>{
    if(!mapa.has(a.turma)){
      mapa.set(a.turma, { codigo:a.turma, curso:a.curso, categoria:a.categoria, unidade:a.unidade });
    }
  });
  const professoresPorCategoria = {};
  NOMES_CATEGORIAS.forEach(cat=>{ professoresPorCategoria[cat] = PROFESSORES.filter(p=>p.categoria===cat); });

  return Array.from(mapa.values()).map(base=>{
    const candidatos = professoresPorCategoria[base.categoria].filter(p=>p.unidade===base.unidade);
    const professor = aleatorio(candidatos.length ? candidatos : PROFESSORES);
    const turno = aleatorio(TURNOS);
    const matriculados = ALUNOS.filter(a=>a.turma===base.codigo && a.status==="Ativo").length;
    return {
      id: ULTIMO_ID_TURMA++,
      codigo: base.codigo, curso: base.curso, categoria: base.categoria, unidade: base.unidade,
      professorId: professor ? professor.id : null,
      turno, horario: HORARIOS_TURNO[turno],
      sala: `Sala ${numeroEntre(1,20)}`,
      capacidade: Math.max(matriculados + numeroEntre(3,15), 20),
      status: "Ativa"
    };
  });
}
function turmasVagas(turma){
  const ocupadas = ALUNOS.filter(a=>a.turma===turma.codigo && a.status==="Ativo").length;
  return Math.max(0, turma.capacidade - ocupadas);
}
function turmasOcupadas(turma){
  return ALUNOS.filter(a=>a.turma===turma.codigo && a.status==="Ativo").length;
}

/* ---------------------------------------------------------
   2.3 FINANCEIRO — mensalidades (contas a receber) e despesas
--------------------------------------------------------- */
let ULTIMO_ID_MENSALIDADE = 1;
let ULTIMO_ID_DESPESA = 1;
const CATEGORIAS_DESPESA = ["Folha de Pagamento","Aluguel","Água, Luz e Internet","Material Didático","Manutenção","Marketing","Outros"];

function gerarMensalidadesDosAlunos(){
  const hoje = new Date();
  const mesReferencia = `${String(hoje.getMonth()+1).padStart(2,"0")}/${hoje.getFullYear()}`;
  return ALUNOS.filter(a=>a.status==="Ativo").map(a=>{
    const valor = Math.max(60, Math.round(precoDoCurso(a.curso)/6/5)*5);
    const diaVenc = numeroEntre(5,25);
    const vencimento = new Date(hoje.getFullYear(), hoje.getMonth(), diaVenc);
    const venceu = vencimento < hoje;
    const roll = Math.random();
    let status;
    if(roll < 0.6) status = "Pago";
    else if(venceu) status = roll < 0.85 ? "Atrasada" : "Pago";
    else status = "Pendente";
    return { id: ULTIMO_ID_MENSALIDADE++, alunoId:a.id, mesReferencia, valor, vencimento: paraInputDate(vencimento), status };
  });
}
function gerarDespesasFicticias(){
  const hoje = new Date();
  const lista = [];
  Object.keys(UNIDADES).forEach(unidade=>{
    CATEGORIAS_DESPESA.forEach(cat=>{
      const valor = cat==="Folha de Pagamento" ? numeroEntre(35000,60000) : numeroEntre(700,6000);
      lista.push({
        id: ULTIMO_ID_DESPESA++, categoria:cat, descricao:cat,
        valor, data: paraInputDate(new Date(hoje.getFullYear(), hoje.getMonth(), numeroEntre(1,28))),
        unidade, status: Math.random() < 0.7 ? "Pago" : "Pendente"
      });
    });
  });
  return lista;
}
function totalReceitasMes(){
  const hoje = new Date();
  const totalPdv = TRANSACOES_PDV.filter(t=>{
    const d = new Date(t.dataHora);
    return d.getMonth()===hoje.getMonth() && d.getFullYear()===hoje.getFullYear();
  }).reduce((s,t)=>s+t.valor, 0);
  const totalMens = mensalidadesVisiveis().filter(m=>m.status==="Pago").reduce((s,m)=>s+m.valor, 0);
  const totalAvulso = RECEBIMENTOS_AVULSOS.filter(r=>{
    if(r.tipo==="mensalidade") return false; // já contado em totalMens
    const d = new Date(r.dataHora);
    return d.getMonth()===hoje.getMonth() && d.getFullYear()===hoje.getFullYear();
  }).reduce((s,r)=>s+r.valor, 0);
  return totalPdv + totalMens + totalAvulso;
}
function totalDespesasMes(){
  return despesasVisiveis().reduce((s,d)=>s+d.valor, 0);
}
function totalInadimplencia(){
  return mensalidadesVisiveis().filter(m=>m.status==="Atrasada").reduce((s,m)=>s+m.valor, 0);
}

