function inicializarModuloCursos(){
  MODULOS_GENERICOS.cursos.dados = [];
  let seq = 1;
  NOMES_CATEGORIAS.forEach(cat=>{
    CATEGORIAS[cat].cursos.forEach(curso=>{
      MODULOS_GENERICOS.cursos.dados.push({
        id: seq++, nome: curso, categoria: cat, cargaHoraria: CATEGORIAS[cat].cargaHoraria,
        modalidade: "Presencial", vagas: 40
      });
    });
  });
}
function recalcularContadorIdGenerico(){
  let maior = 0;
  Object.values(MODULOS_GENERICOS).forEach(m=> m.dados.forEach(d=>{ if(d.id > maior) maior = d.id; }));
  CONTADOR_ID_GENERICO = maior + 1;
}

/* ---------------------------------------------------------
   3.2 MOTOR GENÉRICO — renderização da lista, modal de novo/editar,
   salvar e excluir. Usado por todos os módulos cadastrados em MODULOS_GENERICOS.
--------------------------------------------------------- */
let MODULO_GENERICO_ATUAL = null;

function opcoesUnidadeHTML(selecionado){
  return Object.keys(UNIDADES).map(k=>
    `<option value="${k}" ${selecionado===k?"selected":""}>${UNIDADES[k].nome}</option>`
  ).join("");
}
function opcoesCursoHTML(selecionado){
  return Object.keys(PRECOS_CURSOS).map(c=>
    `<option value="${c}" ${selecionado===c?"selected":""}>${c}</option>`
  ).join("");
}
function opcoesAlunoHTML(selecionado){
  return alunosVisiveis().slice(0,300).map(a=>
    `<option value="${a.id}" ${String(selecionado)===String(a.id)?"selected":""}>${a.nome} — ${a.matricula}</option>`
  ).join("");
}

function renderizarGenerico(chave){
  const mod = MODULOS_GENERICOS[chave];
  if(!mod) return;
  MODULO_GENERICO_ATUAL = chave;
  document.getElementById("generico-titulo").textContent = mod.titulo;
  document.getElementById("generico-descricao").textContent = mod.descricao || "";
  document.getElementById("topbar-titulo").textContent = mod.titulo;

  const widgetsWrap = document.getElementById("comunicados-widgets");
  const permWrap = document.getElementById("permissoes-widgets");
  const tabelaWrap = document.getElementById("generico-tabela-wrap");
  const btnNovo = document.getElementById("btn-novo-generico");

  if(chave === "comunicados"){
    widgetsWrap.classList.remove("oculto");
    permWrap.classList.add("oculto");
    tabelaWrap.classList.add("oculto");
    if(btnNovo) btnNovo.classList.remove("oculto");
    renderizarComunicadosWidgets(mod);
    return;
  }
  if(chave === "permissoes"){
    widgetsWrap.classList.add("oculto");
    permWrap.classList.remove("oculto");
    tabelaWrap.classList.add("oculto");
    if(btnNovo) btnNovo.classList.add("oculto");
    renderizarMatrizPermissoes();
    return;
  }
  widgetsWrap.classList.add("oculto");
  permWrap.classList.add("oculto");
  tabelaWrap.classList.remove("oculto");
  if(btnNovo) btnNovo.classList.remove("oculto");

  const camposVisiveis = mod.campos.slice(0, 6);
  document.getElementById("generico-thead").innerHTML =
    camposVisiveis.map(c=>`<th>${c.label}</th>`).join("") + "<th></th>";

  const linhas = mod.dados.map(item=>{
    const tds = camposVisiveis.map(c=>{
      let valor = item[c.id];
      if(c.tipo === "select-aluno"){
        const a = ALUNOS.find(al=>String(al.id)===String(valor));
        valor = a ? a.nome : (valor || "—");
      } else if(c.tipo === "select-unidade"){
        valor = valor === "todas" ? "Todas as unidades" : ((UNIDADES[valor]||{}).nome || valor || "—");
      } else if(c.tipo === "data" && valor){
        valor = formatarData(valor);
      }
      return `<td>${valor!==undefined && valor!==null && valor!=="" ? valor : "—"}</td>`;
    }).join("");
    return `<tr onclick="abrirModalGenerico('${chave}', ${item.id})" style="cursor:pointer;">${tds}<td><span class="link-editar">✎</span></td></tr>`;
  }).join("");

  document.getElementById("generico-tbody").innerHTML = linhas ||
    `<tr><td colspan="${camposVisiveis.length+1}" style="text-align:center;padding:24px;color:#9aa3b8;">Nenhum registro cadastrado ainda. Clique em "+ Novo" para adicionar.</td></tr>`;
}

/* ---------------------------------------------------------
   3.2c CENTRAL DE ATENDIMENTO — chat interno com alunos/responsáveis
   (dados fictícios em memória, sem backend; ver docs/roadmap)
--------------------------------------------------------- */
let ATEND_CONVERSAS = null;
let ATEND_CONVERSA_ATIVA = null;
let ATEND_FILTRO = "todas";
let ATEND_EVENTOS_LIGADOS = false;

const ATEND_MENSAGENS_MODELO = {
  pt: {
    recebidas: ["Boa tarde", "Olá, tudo bem?", "Gostaria de saber sobre a segunda via do boleto.",
      "Preciso da declaração de matrícula, como faço?", "Obrigado(a) pela ajuda!", "Vocês podem confirmar o horário da prova?"],
    enviadas: ["Boa tarde! Em que posso ajudar?", "Claro, já vou verificar para você.",
      "Segue em anexo o documento solicitado.", "Qualquer dúvida, estamos à disposição."]
  }
};

function iniciaisNome(nome){
  const partes = (nome || "").trim().split(/\s+/);
  return ((partes[0]?.[0] || "") + (partes[1]?.[0] || "")).toUpperCase();
}

function construirConversasAtendimento(){
  if(!ALUNOS || !ALUNOS.length){ ATEND_CONVERSAS = []; return; }
  const amostra = ALUNOS.slice(0, 220).filter((a,i)=> i % 17 === 0).slice(0, 14);
  const agora = Date.now();
  ATEND_CONVERSAS = amostra.map((aluno, idx) => {
    const contato = aluno.responsavel ? aluno.responsavel.nome : aluno.nome;
    const unidadeNome = (UNIDADES[aluno.unidade] && UNIDADES[aluno.unidade].nome) || aluno.unidade;
    const qtdMsgs = 2 + (idx % 3);
    const mensagens = [];
    for(let i=0; i<qtdMsgs; i++){
      const de = i % 2 === 0 ? "contato" : "equipe";
      const banco = de === "contato" ? ATEND_MENSAGENS_MODELO.pt.recebidas : ATEND_MENSAGENS_MODELO.pt.enviadas;
      mensagens.push({
        de,
        texto: banco[(idx + i) % banco.length],
        quando: agora - (qtdMsgs - i) * 3600_000 * (idx % 5 + 1)
      });
    }
    const naoLida = idx % 4 === 0;
    return {
      id: aluno.id,
      nome: contato,
      aluno: aluno.nome,
      unidade: unidadeNome,
      turma: aluno.turma,
      avatar: iniciaisNome(contato),
      naoLida,
      mensagens
    };
  });
}

function formatarHoraMsgAtendimento(timestamp){
  const d = new Date(timestamp);
  return `${formatarData(paraInputDate(d))} ${d.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}`;
}

function listaFiltradaAtendimento(){
  const termo = normalizarTextoIA((document.getElementById("atend-busca-input")?.value || "").trim());
  return ATEND_CONVERSAS.filter(c => {
    if(ATEND_FILTRO === "naolidas" && !c.naoLida) return false;
    if(!termo) return true;
    return normalizarTextoIA(c.nome).includes(termo) || normalizarTextoIA(c.aluno).includes(termo);
  });
}

function renderizarListaConversasAtendimento(){
  const cont = document.getElementById("atend-conversas");
  if(!cont) return;
  const lista = listaFiltradaAtendimento();
  const statusEl = document.getElementById("atend-contador-status");
  if(statusEl) statusEl.textContent = `${t("atend.atualizando")} · ${ATEND_CONVERSAS.length}`;

  if(!lista.length){
    cont.innerHTML = `<div class="atend-vazio">${t("atend.semresultado")}</div>`;
    return;
  }

  cont.innerHTML = lista.map(c => {
    const ultima = c.mensagens[c.mensagens.length - 1];
    const preview = ultima ? (ultima.texto.length > 42 ? ultima.texto.slice(0,42)+"…" : ultima.texto) : "";
    const ativa = ATEND_CONVERSA_ATIVA && ATEND_CONVERSA_ATIVA.id === c.id;
    return `
      <button type="button" class="atend-item${ativa ? " ativo" : ""}" onclick="abrirConversaAtendimento(${c.id})">
        <span class="atend-avatar">${c.avatar}</span>
        <span class="atend-item-corpo">
          <span class="atend-item-linha1"><b>${c.nome}</b>${c.naoLida ? '<span class="atend-badge-naolida"></span>' : ""}</span>
          <span class="atend-item-sub">${c.unidade} · ${c.turma}</span>
          <span class="atend-item-preview">${preview}</span>
        </span>
      </button>`;
  }).join("");
}

function abrirConversaAtendimento(id){
  const c = ATEND_CONVERSAS.find(x => x.id === id);
  if(!c) return;
  c.naoLida = false;
  ATEND_CONVERSA_ATIVA = c;

  document.getElementById("atend-thread-vazio").classList.add("oculto");
  document.getElementById("atend-thread-conteudo").classList.remove("oculto");
  document.getElementById("atend-thread-avatar").textContent = c.avatar;
  document.getElementById("atend-thread-nome").textContent = c.nome;
  document.getElementById("atend-thread-sub").textContent = `${c.unidade} · ${c.turma}`;

  renderizarMensagensAtendimento();
  renderizarListaConversasAtendimento();
}

function renderizarMensagensAtendimento(){
  const cont = document.getElementById("atend-thread-mensagens");
  if(!cont || !ATEND_CONVERSA_ATIVA) return;
  cont.innerHTML = ATEND_CONVERSA_ATIVA.mensagens.map(m => `
    <div class="atend-msg atend-msg-${m.de === "equipe" ? "equipe" : "contato"}">
      <p>${m.texto}</p>
      <span>${formatarHoraMsgAtendimento(m.quando)}</span>
    </div>`).join("");
  cont.scrollTop = cont.scrollHeight;
}

function enviarMensagemAtendimento(ev){
  ev.preventDefault();
  const input = document.getElementById("atend-thread-input");
  const texto = input.value.trim();
  if(!texto || !ATEND_CONVERSA_ATIVA) return;
  ATEND_CONVERSA_ATIVA.mensagens.push({ de:"equipe", texto, quando: Date.now() });
  input.value = "";
  renderizarMensagensAtendimento();
  renderizarListaConversasAtendimento();
}

function renderizarAtendimento(){
  if(!ATEND_CONVERSAS) construirConversasAtendimento();
  renderizarListaConversasAtendimento();

  if(ATEND_EVENTOS_LIGADOS) return;
  ATEND_EVENTOS_LIGADOS = true;

  document.getElementById("atend-busca-input").addEventListener("input", renderizarListaConversasAtendimento);
  document.querySelectorAll(".atend-filtro").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".atend-filtro").forEach(b => b.classList.remove("ativo"));
      btn.classList.add("ativo");
      ATEND_FILTRO = btn.dataset.filtroAtend;
      renderizarListaConversasAtendimento();
    });
  });
  document.getElementById("atend-thread-form").addEventListener("submit", enviarMensagemAtendimento);
  document.getElementById("atend-msg-padronizada").addEventListener("change", (e) => {
    if(e.target.value){
      document.getElementById("atend-thread-input").value = e.target.value;
      document.getElementById("atend-thread-input").focus();
    }
    e.target.selectedIndex = 0;
  });
  document.getElementById("atend-btn-anexo").addEventListener("click", () => {
    mostrarToast("Anexo de arquivos ainda não disponível nesta versão de demonstração.");
  });
  document.getElementById("atend-thread-input").addEventListener("keydown", (e) => {
    if(e.key === "Enter" && !e.shiftKey){
      e.preventDefault();
      document.getElementById("atend-thread-form").requestSubmit();
    }
  });
}


const COM_BADGE_POR_DESTINATARIO = {
  "Todos os alunos": { classe:"com-badge-alunos", curto:"Alunos" },
  "Todos os professores": { classe:"com-badge-professores", curto:"Professores" },
  "Uma turma": { classe:"com-badge-turma", curto:"Turma" },
  "Responsáveis": { classe:"com-badge-responsaveis", curto:"Responsáveis" }
};
let COM_FILTRO_ATIVO = "todos";

function renderizarComunicadosWidgets(mod){
  const dados = mod.dados.slice().sort((a,b)=> new Date(b.data||0) - new Date(a.data||0));
  const agora = new Date();
  const mesAtual = agora.getMonth(), anoAtual = agora.getFullYear();

  const total = dados.length;
  const esteMes = dados.filter(d=>{
    if(!d.data) return false;
    const dt = new Date(d.data+"T00:00:00");
    return dt.getMonth()===mesAtual && dt.getFullYear()===anoAtual;
  }).length;

  const contagemDest = {};
  dados.forEach(d=>{ contagemDest[d.destinatario] = (contagemDest[d.destinatario]||0) + 1; });
  const destinatarioTop = Object.keys(contagemDest).sort((a,b)=>contagemDest[b]-contagemDest[a])[0];

  const maisRecente = dados[0];

  document.getElementById("comunicados-resumo").innerHTML = `
    <div class="com-resumo-card">
      <span class="com-resumo-icone" style="background:#e5edff;color:#1f6ae0;">${svgIcone("megaphone")}</span>
      <span class="com-resumo-valor">${total}</span>
      <span class="com-resumo-label">Total de comunicados</span>
    </div>
    <div class="com-resumo-card">
      <span class="com-resumo-icone" style="background:var(--verde-bg);color:var(--verde);">${svgIcone("calendar")}</span>
      <span class="com-resumo-valor">${esteMes}</span>
      <span class="com-resumo-label">Enviados este mês</span>
    </div>
    <div class="com-resumo-card">
      <span class="com-resumo-icone" style="background:var(--roxo-bg);color:var(--roxo);">${svgIcone("users")}</span>
      <span class="com-resumo-valor">${destinatarioTop ? (COM_BADGE_POR_DESTINATARIO[destinatarioTop]||{}).curto || destinatarioTop : "—"}</span>
      <span class="com-resumo-label">Destinatário mais usado</span>
      <span class="com-resumo-nota">${destinatarioTop ? `${contagemDest[destinatarioTop]} comunicado(s)` : "Nenhum envio ainda"}</span>
    </div>
    <div class="com-resumo-card">
      <span class="com-resumo-icone" style="background:var(--ambar-bg);color:var(--ambar);">${svgIcone("clock")}</span>
      <span class="com-resumo-valor">${maisRecente ? formatarData(maisRecente.data) : "—"}</span>
      <span class="com-resumo-label">Último enviado</span>
      <span class="com-resumo-nota">${maisRecente ? (maisRecente.titulo||"") : "Nenhum comunicado cadastrado"}</span>
    </div>
  `;

  const opcoesFiltro = [{ chave:"todos", rotulo:"Todos" }]
    .concat(Object.keys(COM_BADGE_POR_DESTINATARIO).map(k=>({ chave:k, rotulo:COM_BADGE_POR_DESTINATARIO[k].curto })));
  document.getElementById("comunicados-filtros").innerHTML = opcoesFiltro.map(op=>
    `<button type="button" class="com-filtro-chip ${COM_FILTRO_ATIVO===op.chave?"ativo":""}" data-filtro-com="${op.chave}">${op.rotulo}</button>`
  ).join("");

  const dadosFiltrados = COM_FILTRO_ATIVO === "todos" ? dados : dados.filter(d=>d.destinatario===COM_FILTRO_ATIVO);

  document.getElementById("comunicados-cards").innerHTML = dadosFiltrados.length ? dadosFiltrados.map(item=>{
    const badge = COM_BADGE_POR_DESTINATARIO[item.destinatario] || { classe:"com-badge-alunos", curto:item.destinatario||"—" };
    return `
      <div class="com-card" onclick="abrirModalGenerico('comunicados', ${item.id})">
        <div class="com-card-cab">
          <span class="com-card-titulo">${item.titulo||"(sem título)"}</span>
          <span class="com-card-data">${item.data ? formatarData(item.data) : "—"}</span>
        </div>
        <p class="com-card-msg">${item.mensagem || "Sem mensagem."}</p>
        <div class="com-card-rodape">
          <span class="com-badge-dest ${badge.classe}">${badge.curto}</span>
        </div>
      </div>
    `;
  }).join("") : `<div class="com-card-vazio">Nenhum comunicado ${COM_FILTRO_ATIVO==="todos"?"cadastrado":"para este filtro"} ainda. Clique em "+ Novo" para adicionar.</div>`;
}

function campoInputHTML(campo, valor){
  const v = valor===undefined || valor===null ? "" : valor;
  const req = campo.obrigatorio ? "required" : "";
  const placeholder = campo.placeholder ? `placeholder="${campo.placeholder}"` : "";
  let controle = "";
  if(campo.tipo === "select"){
    controle = `<select id="gn-campo-${campo.id}" ${req}>` +
      (campo.obrigatorio ? "" : `<option value=""></option>`) +
      campo.opcoes.map(o=>`<option value="${o}" ${v===o?"selected":""}>${o}</option>`).join("") + `</select>`;
  } else if(campo.tipo === "select-curso"){
    controle = `<select id="gn-campo-${campo.id}" ${req}><option value=""></option>${opcoesCursoHTML(v)}</select>`;
  } else if(campo.tipo === "select-unidade"){
    controle = `<select id="gn-campo-${campo.id}" ${req}><option value=""></option><option value="todas" ${v==="todas"?"selected":""}>Todas as unidades</option>${opcoesUnidadeHTML(v)}</select>`;
  } else if(campo.tipo === "select-aluno"){
    controle = `<select id="gn-campo-${campo.id}" ${req}><option value=""></option>${opcoesAlunoHTML(v)}</select>`;
  } else if(campo.tipo === "texto-longo"){
    controle = `<textarea id="gn-campo-${campo.id}" rows="3" ${placeholder} ${req}>${v}</textarea>`;
  } else if(campo.tipo === "numero"){
    const min = campo.min!==undefined ? `min="${campo.min}"` : "";
    const max = campo.max!==undefined ? `max="${campo.max}"` : "";
    const step = campo.step ? `step="${campo.step}"` : "";
    controle = `<input type="number" id="gn-campo-${campo.id}" value="${v}" ${min} ${max} ${step} ${req}>`;
  } else if(campo.tipo === "data"){
    controle = `<input type="date" id="gn-campo-${campo.id}" value="${v}" ${req}>`;
  } else if(campo.tipo === "hora"){
    controle = `<input type="time" id="gn-campo-${campo.id}" value="${v}" ${req}>`;
  } else {
    controle = `<input type="text" id="gn-campo-${campo.id}" value="${v}" ${placeholder} ${req}>`;
  }
  const largo = (campo.tipo === "texto-longo") ? "col-2" : "";
  return `<label class="${largo}">${campo.label}${controle}</label>`;
}

function abrirModalGenerico(chave, id){
  const mod = MODULOS_GENERICOS[chave];
  if(!mod) return;
  MODULO_GENERICO_ATUAL = chave;
  const item = id ? mod.dados.find(d=>d.id===id) : null;
  document.getElementById("modal-generico-titulo").textContent = item ? `Editar — ${mod.titulo}` : `Novo — ${mod.titulo}`;
  document.getElementById("gn-id").value = item ? item.id : "";
  document.getElementById("generico-campos").innerHTML = mod.campos.map(c=>campoInputHTML(c, item ? item[c.id] : "")).join("");
  document.getElementById("btn-excluir-generico").classList.toggle("oculto", !item);
  document.getElementById("modal-generico").classList.remove("oculto");
}
function fecharModalGenerico(){
  document.getElementById("modal-generico").classList.add("oculto");
}
function salvarGenerico(ev){
  ev.preventDefault();
  const chave = MODULO_GENERICO_ATUAL;
  const mod = MODULOS_GENERICOS[chave];
  if(!mod) return;
  const idTxt = document.getElementById("gn-id").value;
  const registro = idTxt ? mod.dados.find(d=>d.id===Number(idTxt)) : { id: CONTADOR_ID_GENERICO++ };
  mod.campos.forEach(c=>{
    const el = document.getElementById(`gn-campo-${c.id}`);
    if(!el) return;
    registro[c.id] = c.tipo === "numero" ? (el.value===""?"":Number(el.value)) : el.value;
  });
  if(!idTxt) mod.dados.push(registro);
  fecharModalGenerico();
  renderizarGenerico(chave);
  mostrarToast("Registro salvo com sucesso.");
  registrarAuditoria(idTxt ? "Edição" : "Criação", mod.titulo, `Registro #${registro.id}`);
}
function excluirGenerico(){
  const chave = MODULO_GENERICO_ATUAL;
  const mod = MODULOS_GENERICOS[chave];
  const idTxt = document.getElementById("gn-id").value;
  if(!mod || !idTxt) return;
  mod.dados = mod.dados.filter(d=>d.id!==Number(idTxt));
  fecharModalGenerico();
  renderizarGenerico(chave);
  mostrarToast("Registro excluído.");
  registrarAuditoria("Exclusão", mod.titulo, `Registro #${idTxt}`);
}
let PAGINA_ATUAL = 1;
const POR_PAGINA = 15;

function carregarDados(){
  ALUNOS = gerarBaseFicticia(500); // alunos distribuídos entre as 5 unidades
  PROFESSORES = gerarBaseProfessores(40); // professores distribuídos entre as 5 unidades
  TURMAS = gerarTurmasDosAlunos();
  MENSALIDADES = gerarMensalidadesDosAlunos();
  DESPESAS = gerarDespesasFicticias();
  TRANSACOES_PDV = [];
  RECEBIMENTOS_AVULSOS = [];
  inicializarModuloCursos();
  recalcularContadorIdGenerico();

  // Vincula as contas de demonstração de "Aluno" e "Professor" a um registro real
  // da unidade BH Sede, para que o autoatendimento (documentos, dados próprios) funcione.
  const contaAluno = USUARIOS.find(u=>u.perfil==="Aluno");
  const alunoDemo = ALUNOS.find(a=>a.unidade==="bhsede");
  if(contaAluno && alunoDemo){
    contaAluno.vinculoId = alunoDemo.id;
    contaAluno.nome = `${alunoDemo.nome} (Aluno)`;
  }
  const contaProfessor = USUARIOS.find(u=>u.perfil==="Professor");
  const professorDemo = PROFESSORES.find(p=>p.unidade==="bhsede");
  if(contaProfessor && professorDemo){
    contaProfessor.vinculoId = professorDemo.id;
    contaProfessor.nome = `${professorDemo.nome} (Professor)`;
  }
}
function professoresVisiveis(){
  if(CURRENT_UNIDADE === "todas") return PROFESSORES;
  return PROFESSORES.filter(p => p.unidade === CURRENT_UNIDADE);
}
function turmasVisiveis(){
  if(CURRENT_UNIDADE === "todas") return TURMAS;
  return TURMAS.filter(t => t.unidade === CURRENT_UNIDADE);
}
function mensalidadesVisiveis(){
  const lista = CURRENT_UNIDADE === "todas" ? MENSALIDADES : MENSALIDADES.filter(m=>{
    const a = ALUNOS.find(al=>al.id===m.alunoId);
    return a && a.unidade === CURRENT_UNIDADE;
  });
  return lista;
}
function despesasVisiveis(){
  if(CURRENT_UNIDADE === "todas") return DESPESAS;
  return DESPESAS.filter(d => d.unidade === CURRENT_UNIDADE);
}

/* ---------------------------------------------------------
   4. NAVEGAÇÃO
--------------------------------------------------------- */
function alternarGrupoMenu(chave){
  const itens = document.querySelector(`.nav-grupo-itens[data-grupo-itens="${chave}"]`);
  const cab = document.querySelector(`.nav-grupo-cab[data-toggle-grupo="${chave}"]`);
  if(!itens || !cab) return;
  const estaFechado = itens.classList.contains("nav-grupo-fechado");
  if(estaFechado) abrirGrupoMenu(chave); else fecharGrupoMenu(chave);
}
function abrirGrupoMenu(chave){
  const itens = document.querySelector(`.nav-grupo-itens[data-grupo-itens="${chave}"]`);
  const cab = document.querySelector(`.nav-grupo-cab[data-toggle-grupo="${chave}"]`);
  if(!itens || !cab) return;
  // Comportamento de acordeão: ao abrir um grupo, fecha os demais para o
  // menu não crescer demais e itens não ficarem "escondidos" lá embaixo.
  document.querySelectorAll(".nav-grupo-itens").forEach(el => {
    if(el.dataset.grupoItens !== chave) fecharGrupoMenu(el.dataset.grupoItens);
  });
  itens.classList.remove("nav-grupo-fechado");
  cab.classList.add("nav-grupo-cab-aberto");
  cab.setAttribute("aria-expanded", "true");
}
function fecharGrupoMenu(chave){
  const itens = document.querySelector(`.nav-grupo-itens[data-grupo-itens="${chave}"]`);
  const cab = document.querySelector(`.nav-grupo-cab[data-toggle-grupo="${chave}"]`);
  if(!itens || !cab) return;
  itens.classList.add("nav-grupo-fechado");
  cab.classList.remove("nav-grupo-cab-aberto");
  cab.setAttribute("aria-expanded", "false");
}
function irParaView(view, elBtn){
  fecharMenuSeMobile();
  document.querySelectorAll(".view").forEach(v => v.classList.add("oculto"));
  document.getElementById(`view-${view}`).classList.remove("oculto");
  document.querySelectorAll(".nav-item").forEach(b => {
    b.classList.toggle("ativo", elBtn ? (b === elBtn) : (b.dataset.view === view && view !== "stub"));
  });
  const itemAtivo = (elBtn && elBtn.closest) ? elBtn : document.querySelector(`.nav-item[data-view="${view}"]`);
  if(itemAtivo && itemAtivo.closest){
    const grupoItens = itemAtivo.closest(".nav-grupo-itens");
    if(grupoItens) abrirGrupoMenu(grupoItens.dataset.grupoItens);
  }
  atualizarTopbar(view);

  if(view === "dashboard") renderizarDashboard();
  if(view === "novidades") renderizarNovidades();
  if(view === "alunos") renderizarTabelaAlunos();
  if(view === "perfil-aluno") renderizarPerfilAluno();
  if(view === "matriculas") renderizarMatriculas();
  if(view === "pdv") { preencherSelectAlunosPDV(); atualizarCursosPDV(); renderizarCaixaDoDia(); }
  if(view === "documentos"){
    preencherSelectAlunos();
    const tipoAlvo = elBtn ? elBtn.dataset.doctipo : null;
    if(tipoAlvo) document.getElementById("doc-tipo").value = tipoAlvo;
    if(document.getElementById("doc-aluno").value) gerarDocumento();
    else document.getElementById("folha-documento").innerHTML = `<div class="doc-vazio">${t("doc.selecione")}</div>`;
  }
  if(view === "relatorios"){
    const relatorioAlvo = elBtn ? elBtn.dataset.relatorioAlvo : null;
    if(relatorioAlvo) gerarRelatorio(relatorioAlvo);
  }
  if(view === "bi") renderizarBI();
  if(view === "portal-aluno") renderizarPortalAluno();
  if(view === "portal-professor") renderizarPortalProfessor();
  if(view === "professores") renderizarTabelaProfessores();
  if(view === "turmas") renderizarTabelaTurmas();
  if(view === "valores") renderizarTabelaValores();
  if(view === "financeiro"){
    const aba = elBtn ? elBtn.dataset.fintab : null;
    if(aba) FIN_ABA_ATUAL = aba;
    renderizarFinanceiro();
  }
  if(view === "stub") renderizarStub(elBtn);
  if(view === "auditoria") renderizarAuditoria();
  if(view === "sessoes") renderizarSessoes();
  if(view === "generico"){
    const modulo = elBtn ? elBtn.dataset.modulo : MODULO_GENERICO_ATUAL;
    if(modulo) renderizarGenerico(modulo);
  }
  if(view === "atendimento") renderizarAtendimento();
}

/* Tela genérica "Em breve" — usada por todos os itens de menu ainda não implementados */
function renderizarStub(elBtn){
  const chave = elBtn ? elBtn.dataset.stub : null;
  const nomeModulo = chave ? t(chave) : "";
  document.getElementById("stub-titulo").textContent = nomeModulo || t("stub.titulo");
  document.getElementById("topbar-titulo").textContent = nomeModulo || t("view.stub.titulo");
}

