let NOVIDADE_INDICE = 0;

function renderizarNovidades(){
  const slide = document.getElementById("novidade-slide");
  const dots = document.getElementById("novidade-dots");
  if(!slide || !dots) return;
  if(NOVIDADE_INDICE >= NOVIDADES.length) NOVIDADE_INDICE = 0;
  if(NOVIDADE_INDICE < 0) NOVIDADE_INDICE = NOVIDADES.length - 1;

  const idioma = IDIOMA_ATUAL;
  const n = NOVIDADES[NOVIDADE_INDICE];
  const rotulo = TAG_ROTULO[n.tag] || TAG_ROTULO.novo;

  slide.className = `carrossel-slide carrossel-slide-${n.tag}`;
  slide.innerHTML = `
    <span class="carrossel-forma carrossel-forma-1"></span>
    <span class="carrossel-forma carrossel-forma-2"></span>
    <div class="carrossel-conteudo">
      <span class="carrossel-tag">${rotulo[idioma] || rotulo.pt}</span>
      <h2 class="carrossel-titulo">${n.titulo[idioma] || n.titulo.pt}</h2>
      <p class="carrossel-texto">${n.descricao[idioma] || n.descricao.pt}</p>
      <div class="carrossel-rodape">
        <button type="button" class="carrossel-cta">${idioma==='en'?'LEARN MORE':(idioma==='es'?'MÁS INFORMACIÓN':'SAIBA MAIS')}</button>
        <span class="carrossel-data">${formatarDataCurta(n.data)}</span>
      </div>
    </div>`;

  dots.innerHTML = NOVIDADES.map((_,i)=>
    `<span class="carrossel-dot ${i===NOVIDADE_INDICE?'ativo':''}" onclick="irParaNovidade(${i})"></span>`
  ).join("");
}
function irParaNovidade(i){ NOVIDADE_INDICE = i; renderizarNovidades(); }
function avancarNovidade(direcao){
  NOVIDADE_INDICE = (NOVIDADE_INDICE + direcao + NOVIDADES.length) % NOVIDADES.length;
  renderizarNovidades();
}
function iniciarAutoNovidades(){
  setInterval(()=>{
    const view = document.getElementById("view-novidades");
    if(view && !view.classList.contains("oculto")) avancarNovidade(1);
  }, 7000);
}

function formatarDataCurta(iso){
  const [ano,mes,dia] = iso.split("-");
  return `${dia}/${mes}/${ano}`;
}

function montarTickerNovidades(){
  const ticker = document.getElementById("ticker-novidades-conteudo");
  if(!ticker) return;
  const idioma = IDIOMA_ATUAL;
  const itens = NOVIDADES.map(n => `📢 ${n.titulo[idioma] || n.titulo.pt}`).join("   •   ");
  // duplica o conteúdo para permitir rolagem contínua sem "salto"
  ticker.innerHTML = `<span>${itens}</span><span>${itens}</span>`;
}

