let INTERVALO_TEMPO_REAL = null;
function iniciarTempoReal(){
  if(INTERVALO_TEMPO_REAL) clearInterval(INTERVALO_TEMPO_REAL);

  // Semeia algumas atividades iniciais para o painel não nascer vazio
  ATIVIDADES_RECENTES = [gerarAtividadeAleatoria(), gerarAtividadeAleatoria(), gerarAtividadeAleatoria()];
  NAO_LIDAS = 3;
  renderNotificacoes();
  renderAtividadesDashboard();
  renderEventosDashboard();
  atualizarCarimboDashboard();

  // Nova atividade simulada a cada 10–20s (como um feed em tempo real via polling/websocket)
  INTERVALO_TEMPO_REAL = setInterval(() => {
    adicionarAtividade(gerarAtividadeAleatoria());
    // Re-renderiza o dashboard (KPIs/gráficos) se estiver na tela, e marca o horário da atualização
    if(!document.getElementById("view-dashboard").classList.contains("oculto")){
      renderizarDashboard();
    }
    atualizarCarimboDashboard();
  }, 10000 + Math.random()*8000);
}
function pararTempoReal(){
  if(INTERVALO_TEMPO_REAL) clearInterval(INTERVALO_TEMPO_REAL);
  INTERVALO_TEMPO_REAL = null;
}
function atualizarCarimboDashboard(){
  const el = document.getElementById("dash-ultima-atualizacao");
  if(el) el.textContent = horaFormatada() + ":" + String(new Date().getSeconds()).padStart(2,"0");
}

