function renderGraficoBIReceitaDespesa(idsAtivos){
  const cont = document.getElementById("grafico-bi-receitadespesa");
  const hoje = new Date();
  const qtdMeses = BI_FILTRO_PERIODO === "ano" ? (hoje.getMonth()+1) : BI_FILTRO_PERIODO;
  const meses = [];
  for(let i=qtdMeses-1;i>=0;i--){
    const d = new Date(hoje.getFullYear(), hoje.getMonth()-i, 1);
    meses.push({ ano:d.getFullYear(), mes:d.getMonth(), label: MESES_ABREV[IDIOMA_ATUAL][d.getMonth()] });
  }
  const filtrarPorCurso = BI_FILTRO_CURSO !== "todos" && idsAtivos;
  const mensBase = mensalidadesVisiveis().filter(m => !filtrarPorCurso || idsAtivos.has(m.alunoId));
  const despBase = despesasVisiveis();
  const receitas = meses.map(m => mensBase.filter(x=>{
    const d = new Date(x.vencimento); return x.status==="Pago" && d.getFullYear()===m.ano && d.getMonth()===m.mes;
  }).reduce((s,x)=>s+x.valor,0));
  const despesas = meses.map(m => despBase.filter(x=>{
    const d = new Date(x.data); return d.getFullYear()===m.ano && d.getMonth()===m.mes;
  }).reduce((s,x)=>s+x.valor,0));

  const tituloEl = document.getElementById("bi-titulo-receitadespesa");
  if(tituloEl){
    const rotuloPeriodo = BI_FILTRO_PERIODO === "ano" ? t("bi.filtro.periodo.ano") : t(`bi.filtro.periodo.${qtdMeses}m`);
    tituloEl.textContent = `${t("bi.receitadespesa")||"Receita x Despesa"} — ${rotuloPeriodo || (qtdMeses+" meses")}`;
  }

  const largura = 900, altura = 220, margem = 30, passo = (largura-margem*2)/Math.max(1,meses.length-1);
  const max = Math.max(...receitas, ...despesas, 1);
  const y = v => altura-40 - (v/max)*(altura-70);

  function construirLinha(valores){
    const pontos = valores.map((v,i)=>[margem+i*passo, y(v)]);
    return pontos.map((p,i)=>(i===0?"M":"L")+p[0]+","+p[1]).join(" ");
  }
  const linhaReceita = construirLinha(receitas);
  const linhaDespesa = construirLinha(despesas);
  const rotulos = meses.map((m,i)=>`<text x="${margem+i*passo}" y="${altura-18}" text-anchor="middle" font-size="10" fill="#8a93a8">${m.label}</text>`).join("");

  cont.innerHTML = `<svg viewBox="0 0 ${largura} ${altura}">
    <path d="${linhaReceita}" fill="none" stroke="#1a9c6b" stroke-width="2.5"/>
    <path d="${linhaDespesa}" fill="none" stroke="#d64545" stroke-width="2.5"/>
    ${rotulos}
  </svg>`;
}

function renderGraficoBIUnidades(base){
  const cont = document.getElementById("grafico-bi-unidades");
  const cores = ["#2569eb","#1a9c6b","#c8860d","#6b3fd6","#d64545"];
  const alunosBase = base || alunosVisiveis();
  const contagens = LISTA_UNIDADES.map(u => alunosBase.filter(a=>a.unidade===u.id).length);
  const max = Math.max(...contagens, 1);
  cont.innerHTML = LISTA_UNIDADES.map((u,i)=>{
    const v = contagens[i];
    const pct = v/max*100;
    return `<div class="barra-linha">
      <span class="barra-label">${u.nome}</span>
      <span class="barra-trilho"><span class="barra-fill" style="width:${pct}%;background:${cores[i%cores.length]}"></span></span>
      <span class="barra-valor">${v}</span>
    </div>`;
  }).join("");
}

function renderGraficoBICursos(base){
  const cont = document.getElementById("grafico-bi-cursos");
  if(!cont) return;
  const alunosBase = base || alunosVisiveis();
  const cores = ["#2569eb","#c8860d","#6b3fd6","#1a9c6b","#d64545","#4f8bf0"];
  const contagem = {};
  alunosBase.forEach(a => contagem[a.curso] = (contagem[a.curso]||0)+1);
  const total = alunosBase.length;
  const entradas = Object.entries(contagem).sort((a,b)=>b[1]-a[1]);
  const top = entradas.slice(0,5);
  const outros = entradas.slice(5).reduce((s,[,v])=>s+v,0);
  if(outros>0) top.push([t("bi.outros")||"Outros", outros]);

  if(!total){ cont.innerHTML = `<p class="texto-info">Nenhum aluno na seleção atual.</p>`; return; }

  let acumulado = 0;
  const raio = 60, cx=80, cy=80, espessura=26;
  const circunferencia = 2*Math.PI*raio;
  let segmentos = "";
  top.forEach(([,valor], i)=>{
    const fracao = valor/total;
    const comprimento = fracao*circunferencia;
    segmentos += `<circle cx="${cx}" cy="${cy}" r="${raio}" fill="none" stroke="${cores[i%cores.length]}"
      stroke-width="${espessura}" stroke-dasharray="${comprimento} ${circunferencia-comprimento}"
      stroke-dashoffset="${-acumulado}" transform="rotate(-90 ${cx} ${cy})"/>`;
    acumulado += comprimento;
  });

  const svg = `<svg viewBox="0 0 160 160" style="max-width:190px;margin:0 auto;display:block;">
    ${segmentos}
    <text x="80" y="76" text-anchor="middle" font-size="22" font-weight="800" fill="#0b1e4a">${total}</text>
    <text x="80" y="94" text-anchor="middle" font-size="10" fill="#8a93a8">${IDIOMA_ATUAL==='en'?'students':(IDIOMA_ATUAL==='es'?'estudiantes':'alunos')}</text>
  </svg>`;

  const legenda = `<div class="legenda">${top.map(([curso,valor],i)=>`
    <div class="legenda-item">
      <span class="legenda-ponto" style="background:${cores[i%cores.length]}"></span>
      ${curso} <b>${valor} (${Math.round(valor/total*100)}%)</b>
    </div>`).join("")}</div>`;

  cont.innerHTML = svg + legenda;
}

function renderGraficoBIOcupacaoTurmas(turmasBase){
  const cont = document.getElementById("grafico-bi-ocupacao");
  const base = (turmasBase || (CURRENT_UNIDADE==="todas" ? TURMAS : TURMAS.filter(tu=>tu.unidade===CURRENT_UNIDADE))).filter(tu=>tu.capacidade>0);
  const linhas = base.map(tu => ({ codigo:tu.codigo, pct: Math.min(100, Math.round(turmasOcupadas(tu)/tu.capacidade*100)) }))
    .sort((a,b)=>b.pct-a.pct).slice(0,8);
  if(!linhas.length){ cont.innerHTML = `<p class="texto-info">Nenhuma turma com capacidade cadastrada.</p>`; return; }
  cont.innerHTML = linhas.map(l=>{
    const cor = l.pct>=90 ? "#d64545" : (l.pct>=70 ? "#c8860d" : "#1a9c6b");
    return `<div class="barra-linha">
      <span class="barra-label">${l.codigo}</span>
      <span class="barra-trilho"><span class="barra-fill" style="width:${l.pct}%;background:${cor}"></span></span>
      <span class="barra-valor">${l.pct}%</span>
    </div>`;
  }).join("");
}

function renderTabelaBIInadimplenciaUnidade(){
  const tbody = document.querySelector("#tabela-bi-inadimplencia tbody");
  const unidadesBase = CURRENT_UNIDADE==="todas" ? LISTA_UNIDADES : LISTA_UNIDADES.filter(u=>u.id===CURRENT_UNIDADE);
  tbody.innerHTML = unidadesBase.map(u=>{
    const alunosUnidade = ALUNOS.filter(a=>a.unidade===u.id && a.status==="Ativo" && (BI_FILTRO_CURSO==="todos" || a.curso===BI_FILTRO_CURSO));
    const idsAlunos = new Set(alunosUnidade.map(a=>a.id));
    const mensAtrasadas = MENSALIDADES.filter(m=>m.status==="Atrasada" && idsAlunos.has(m.alunoId));
    const valorAtraso = mensAtrasadas.reduce((s,m)=>s+m.valor,0);
    const qtdAlunos = new Set(mensAtrasadas.map(m=>m.alunoId)).size;
    const pct = alunosUnidade.length ? Math.round(qtdAlunos/alunosUnidade.length*100) : 0;
    return `<tr><td>${u.nome}</td><td>${moeda(valorAtraso)}</td><td>${qtdAlunos}</td><td>${pct}%</td></tr>`;
  }).join("");
}

function renderGraficoCategorias(){
  const cont = document.getElementById("grafico-categorias");
  const contagem = {};
  NOMES_CATEGORIAS.forEach(c=>contagem[c]=0);
  alunosVisiveis().forEach(a=>contagem[a.categoria]++);
  const max = Math.max(...Object.values(contagem));

  cont.innerHTML = NOMES_CATEGORIAS.map(cat=>{
    const v = contagem[cat];
    const pct = max ? (v/max*100) : 0;
    return `<div class="barra-linha">
      <span class="barra-label">${t(CHAVE_CATEGORIA[cat])}</span>
      <span class="barra-trilho"><span class="barra-fill" style="width:${pct}%;background:${CORES_CATEGORIA[cat]}"></span></span>
      <span class="barra-valor">${v}</span>
    </div>`;
  }).join("");
}

function renderGraficoStatus(){
  const cont = document.getElementById("grafico-status");
  const contagem = {};
  STATUS_LISTA_UNICA().forEach(s=>contagem[s]=0);
  const baseStatus = alunosVisiveis();
  baseStatus.forEach(a=>contagem[a.status]++);
  const total = baseStatus.length;

  let acumulado = 0;
  const raio = 60, cx=80, cy=80, espessura=26;
  const circunferencia = 2*Math.PI*raio;
  let segmentos = "";
  Object.entries(contagem).forEach(([status,valor])=>{
    if(valor===0) return;
    const fracao = valor/total;
    const comprimento = fracao*circunferencia;
    segmentos += `<circle cx="${cx}" cy="${cy}" r="${raio}" fill="none" stroke="${CORES_STATUS[status]}"
      stroke-width="${espessura}" stroke-dasharray="${comprimento} ${circunferencia-comprimento}"
      stroke-dashoffset="${-acumulado}" transform="rotate(-90 ${cx} ${cy})"/>`;
    acumulado += comprimento;
  });

  const svg = `<svg viewBox="0 0 160 160" style="max-width:190px;margin:0 auto;display:block;">
    ${segmentos}
    <text x="80" y="76" text-anchor="middle" font-size="22" font-weight="800" fill="#0b1e4a">${total}</text>
    <text x="80" y="94" text-anchor="middle" font-size="10" fill="#8a93a8">${IDIOMA_ATUAL==='en'?'students':(IDIOMA_ATUAL==='es'?'estudiantes':'alunos')}</text>
  </svg>`;

  const legenda = `<div class="legenda">${Object.entries(contagem).map(([status,valor])=>`
    <div class="legenda-item">
      <span class="legenda-ponto" style="background:${CORES_STATUS[status]}"></span>
      ${t(CHAVE_STATUS[status])} <b>${valor}</b>
    </div>`).join("")}</div>`;

  cont.innerHTML = svg + legenda;
}
function STATUS_LISTA_UNICA(){ return ["Ativo","Concluído","Trancado","Evadido"]; }

const MESES_ABREV = {
  pt:["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"],
  en:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],
  es:["ene","feb","mar","abr","may","jun","jul","ago","sep","oct","nov","dic"]
};

function renderGraficoEvolucao(){
  const cont = document.getElementById("grafico-evolucao");
  const hoje = new Date();
  const meses = [];
  for(let i=11;i>=0;i--){
    const d = new Date(hoje.getFullYear(), hoje.getMonth()-i, 1);
    meses.push({ ano:d.getFullYear(), mes:d.getMonth(), label: MESES_ABREV[IDIOMA_ATUAL][d.getMonth()] });
  }
  const baseEvolucao = alunosVisiveis();
  const contagens = meses.map(m => baseEvolucao.filter(a=>{
    const dm = new Date(a.dataMatricula);
    return dm.getFullYear()===m.ano && dm.getMonth()===m.mes;
  }).length);
  const max = Math.max(...contagens, 1);

  const largura = 900, altura = 220, margem = 30, passo = (largura-margem*2)/(meses.length-1);
  const pontos = contagens.map((v,i)=>{
    const x = margem + i*passo;
    const y = altura-40 - (v/max)*(altura-70);
    return [x,y];
  });
  const linha = pontos.map((p,i)=> (i===0?"M":"L")+p[0]+","+p[1]).join(" ");
  const area = linha + ` L${pontos[pontos.length-1][0]},${altura-40} L${pontos[0][0]},${altura-40} Z`;

  const circulos = pontos.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#2569eb"/>
    <text x="${p[0]}" y="${p[1]-10}" text-anchor="middle" font-size="10" fill="#0b1e4a" font-weight="700">${contagens[i]}</text>`).join("");
  const rotulos = pontos.map((p,i)=>`<text x="${p[0]}" y="${altura-18}" text-anchor="middle" font-size="10" fill="#8a93a8">${meses[i].label}</text>`).join("");

  cont.innerHTML = `<svg viewBox="0 0 ${largura} ${altura}">
    <defs><linearGradient id="gradEvo" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#2569eb" stop-opacity="0.28"/>
      <stop offset="100%" stop-color="#2569eb" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${area}" fill="url(#gradEvo)"/>
    <path d="${linha}" fill="none" stroke="#2569eb" stroke-width="2.5"/>
    ${circulos}${rotulos}
  </svg>`;
}

function renderGraficoCursos(){
  const cont = document.getElementById("grafico-cursos");
  const contagem = {};
  alunosVisiveis().forEach(a=> contagem[a.curso] = (contagem[a.curso]||0)+1 );
  const top = Object.entries(contagem).sort((a,b)=>b[1]-a[1]).slice(0,6);
  const max = Math.max(...top.map(t=>t[1]));

  cont.innerHTML = top.map(([curso,v])=>{
    const pct = (v/max*100);
    const categoriaDoCurso = NOMES_CATEGORIAS.find(c => CATEGORIAS[c].cursos.includes(curso));
    return `<div class="barra-linha">
      <span class="barra-label">${curso}</span>
      <span class="barra-trilho"><span class="barra-fill" style="width:${pct}%;background:${CORES_CATEGORIA[categoriaDoCurso]}"></span></span>
      <span class="barra-valor">${v}</span>
    </div>`;
  }).join("");
}

function renderGraficoIdade(){
  const cont = document.getElementById("grafico-idade");
  const sufixo = IDIOMA_ATUAL==='en' ? 'yrs' : 'anos';
  const faixas = [["14-17",0,17],["18-24",18,24],["25-34",25,34],["35-44",35,44],["45+",45,120]];
  const cores = ["#4f8bf0","#2569eb","#1a9c6b","#c8860d","#6b3fd6"];
  const baseIdade = alunosVisiveis();
  const contagens = faixas.map(([,min,max]) => baseIdade.filter(a=>{
    const idade = calcularIdade(new Date(a.nascimento));
    return idade>=min && idade<=max;
  }).length);
  const maxV = Math.max(...contagens,1);

  cont.innerHTML = faixas.map(([label],i)=>{
    const pct = contagens[i]/maxV*100;
    return `<div class="barra-linha">
      <span class="barra-label">${label} ${sufixo}</span>
      <span class="barra-trilho"><span class="barra-fill" style="width:${pct}%;background:${cores[i]}"></span></span>
      <span class="barra-valor">${contagens[i]}</span>
    </div>`;
  }).join("");
}

function renderTabelaRecentes(){
  const recentes = [...alunosVisiveis()].sort((a,b)=> new Date(b.dataMatricula)-new Date(a.dataMatricula)).slice(0,8);
  document.getElementById("tabela-recentes").innerHTML = recentes.map(a=>`
    <tr><td>${a.nome}</td><td>${a.curso}</td><td>${formatarData(a.dataMatricula)}</td></tr>
  `).join("");
}

