/* ---------------------------------------------------------
   10. MÓDULO TURMAS — cadastro, edição e vagas
--------------------------------------------------------- */
function nomeProfessor(id){
  const p = PROFESSORES.find(p=>p.id===id);
  return p ? p.nome : "— sem professor —";
}

function obterTurmasFiltradas(){
  const busca = document.getElementById("busca-turma").value.trim().toLowerCase();
  const categoria = document.getElementById("filtro-turma-categoria").value;
  const turno = document.getElementById("filtro-turma-turno").value;
  return turmasVisiveis().filter(tu=>{
    if(busca && !(tu.codigo.toLowerCase().includes(busca) || tu.curso.toLowerCase().includes(busca) || nomeProfessor(tu.professorId).toLowerCase().includes(busca))) return false;
    if(categoria && tu.categoria !== categoria) return false;
    if(turno && tu.turno !== turno) return false;
    return true;
  });
}

function renderizarTabelaTurmas(){
  const lista = obterTurmasFiltradas();
  document.getElementById("tabela-turmas").innerHTML = lista.map(tu=>{
    const matriculados = turmasOcupadas(tu);
    const vagas = turmasVagas(tu);
    return `<tr>
      <td><b>${tu.codigo}</b></td>
      <td>${tu.curso}</td>
      <td>${tu.categoria}</td>
      <td>${nomeProfessor(tu.professorId)}</td>
      <td>${tu.turno} · ${tu.horario}</td>
      <td>${tu.sala}</td>
      <td>${matriculados} / ${tu.capacidade}</td>
      <td><span class="badge badge-${vagas>0?'Ativo':'Evadido'}">${vagas>0?vagas+' vaga(s)':'Lotada'}</span></td>
      <td>${UNIDADES[tu.unidade].nome}</td>
      <td class="acoes-tabela">
        <button class="btn-icone" title="Editar" onclick="abrirModalTurma(${tu.id})">✏️</button>
      </td>
    </tr>`;
  }).join("") || `<tr><td colspan="10" style="text-align:center;padding:24px;color:#9aa3b8;">—</td></tr>`;
}

function preencherSelectProfessoresTurma(categoria, unidade, selecionadoId){
  const select = document.getElementById("tu-professor");
  const candidatos = PROFESSORES.filter(p=>p.unidade===unidade);
  select.innerHTML = `<option value="">— sem professor —</option>` + candidatos.map(p=>`<option value="${p.id}">${p.nome} (${p.categoria})</option>`).join("");
  select.value = selecionadoId || "";
}

function abrirModalTurma(id){
  const turma = id ? TURMAS.find(tu=>tu.id===id) : null;
  document.getElementById("form-turma").reset();
  document.getElementById("modal-turma-titulo").textContent = turma ? "Editar Turma" : "Nova Turma";
  document.getElementById("tu-id").value = turma ? turma.id : "";
  document.getElementById("tu-codigo").value = turma ? turma.codigo : "";
  document.getElementById("tu-categoria").value = turma ? turma.categoria : NOMES_CATEGORIAS[0];
  preencherSelectCursos(document.getElementById("tu-curso"), document.getElementById("tu-categoria").value);
  if(turma) document.getElementById("tu-curso").value = turma.curso;
  document.getElementById("tu-unidade").value = turma ? turma.unidade : (CURRENT_UNIDADE==="todas"?"bhsede":CURRENT_UNIDADE);
  preencherSelectProfessoresTurma(document.getElementById("tu-categoria").value, document.getElementById("tu-unidade").value, turma ? turma.professorId : null);
  document.getElementById("tu-turno").value = turma ? turma.turno : "Manhã";
  document.getElementById("tu-horario").value = turma ? turma.horario : HORARIOS_TURNO["Manhã"];
  document.getElementById("tu-sala").value = turma ? turma.sala : "";
  document.getElementById("tu-capacidade").value = turma ? turma.capacidade : 30;
  document.getElementById("tu-status").value = turma ? turma.status : "Ativa";
  document.getElementById("btn-excluir-turma").classList.toggle("oculto", !turma);
  document.getElementById("modal-turma").classList.remove("oculto");
}
function fecharModalTurma(){ document.getElementById("modal-turma").classList.add("oculto"); }

function salvarTurma(ev){
  ev.preventDefault();
  const id = document.getElementById("tu-id").value;
  const capacidade = Number(document.getElementById("tu-capacidade").value) || 30;
  const codigoNovo = document.getElementById("tu-codigo").value.trim();
  const dados = {
    codigo: codigoNovo,
    categoria: document.getElementById("tu-categoria").value,
    curso: document.getElementById("tu-curso").value,
    professorId: document.getElementById("tu-professor").value ? Number(document.getElementById("tu-professor").value) : null,
    turno: document.getElementById("tu-turno").value,
    horario: document.getElementById("tu-horario").value.trim() || HORARIOS_TURNO[document.getElementById("tu-turno").value],
    sala: document.getElementById("tu-sala").value.trim(),
    capacidade,
    unidade: document.getElementById("tu-unidade").value,
    status: document.getElementById("tu-status").value
  };
  if(id){
    const turma = TURMAS.find(tu=>tu.id===Number(id));
    const codigoAntigo = turma.codigo;
    Object.assign(turma, dados);
    if(codigoAntigo !== codigoNovo){
      ALUNOS.forEach(a=>{ if(a.turma===codigoAntigo) a.turma = codigoNovo; });
    }
    mostrarToast("Turma atualizada com sucesso.");
    registrarAuditoria("Edição", "Turmas", codigoNovo);
    fecharModalTurma();
    renderizarTabelaTurmas();
    if(NexusDB.estaConfigurado()){
      NexusDB.enviarTurmas([turma]).then(r=>{ if(!r.ok) mostrarToast("Aviso: não foi possível sincronizar com o banco."); });
    }
  } else {
    const novaTurma = { id: ULTIMO_ID_TURMA++, ...dados };
    TURMAS.push(novaTurma);
    mostrarToast("Turma cadastrada com sucesso.");
    registrarAuditoria("Criação", "Turmas", codigoNovo);
    fecharModalTurma();
    renderizarTabelaTurmas();
    if(NexusDB.estaConfigurado()){
      NexusDB.enviarTurmas([novaTurma]).then(r=>{ if(!r.ok) mostrarToast("Aviso: não foi possível sincronizar com o banco."); });
    }
  }
}
function excluirTurma(){
  const id = Number(document.getElementById("tu-id").value);
  if(!id) return;
  const turma = TURMAS.find(tu=>tu.id===id);
  if(turma && turmasOcupadas(turma) > 0){
    alert("Não é possível excluir uma turma com alunos matriculados. Remaneje os alunos antes de excluir.");
    return;
  }
  if(!confirm("Deseja realmente excluir esta turma?")) return;
  TURMAS = TURMAS.filter(tu=>tu.id!==id);
  fecharModalTurma();
  renderizarTabelaTurmas();
  mostrarToast("Turma excluída.");
  if(NexusDB.estaConfigurado()){
    NexusDB.excluirTurma(id).then(r=>{ if(!r.ok) mostrarToast("Aviso: não foi possível excluir no banco."); });
  }
  registrarAuditoria("Exclusão", "Turmas", turma ? turma.codigo : `#${id}`);
}

/* ---------------------------------------------------------
   11. MÓDULO VALORES DOS CURSOS — tabela de preços editável (usada pelo PDV)
--------------------------------------------------------- */
function renderizarTabelaValores(){
  const filtroCategoria = document.getElementById("filtro-valores-categoria").value;
  const linhas = [];
  NOMES_CATEGORIAS.forEach(cat=>{
    if(filtroCategoria && filtroCategoria !== cat) return;
    CATEGORIAS[cat].cursos.forEach(curso=>{
      linhas.push({ curso, categoria:cat, cargaHoraria: CATEGORIAS[cat].cargaHoraria, preco: precoDoCurso(curso) });
    });
  });
  document.getElementById("tabela-valores").innerHTML = linhas.map(l=>`
    <tr>
      <td>${l.curso}</td>
      <td>${l.categoria}</td>
      <td>${l.cargaHoraria}</td>
      <td><input type="number" step="0.01" min="0" class="input-valor-curso" data-curso="${l.curso}" value="${l.preco.toFixed(2)}" style="width:120px;"></td>
      <td class="acoes-tabela">
        <button class="btn btn-outline" onclick="salvarValorCurso('${l.curso.replace(/'/g,"\\'")}')">Salvar</button>
      </td>
    </tr>
  `).join("") || `<tr><td colspan="5" style="text-align:center;padding:24px;color:#9aa3b8;">—</td></tr>`;
}

function salvarValorCurso(curso){
  const input = document.querySelector(`.input-valor-curso[data-curso="${CSS.escape(curso)}"]`);
  if(!input) return;
  const novoValor = Math.max(0, Number(input.value) || 0);
  PRECOS_CURSOS[curso] = novoValor;
  document.getElementById("status-valores").textContent = `Valor de "${curso}" atualizado para ${moeda(novoValor)}.`;
  mostrarToast(`Valor de "${curso}" atualizado para ${moeda(novoValor)}.`);
  if(!document.getElementById("view-pdv").classList.contains("oculto")) atualizarCursosPDV();
}

function mostrarToast(msg){
  const toast = document.getElementById("toast");
  toast.textContent = msg;
  toast.classList.remove("oculto");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=> toast.classList.add("oculto"), 2600);
}

/* ---------------------------------------------------------
   10. EXPORTAÇÃO CSV
--------------------------------------------------------- */
function exportarCSV(){
  const cabecalho = ["Matrícula","Nome","Idade","Categoria","Curso","Turma","Situação","CPF","Telefone","E-mail","Responsável","CPF Responsável","Telefone Responsável"];
  const linhas = alunosVisiveis().map(a=>[
    a.matricula, a.nome, calcularIdade(new Date(a.nascimento)), a.categoria, a.curso, a.turma, a.status,
    a.cpf, a.telefone, a.email,
    a.responsavel?a.responsavel.nome:"", a.responsavel?a.responsavel.cpf:"", a.responsavel?a.responsavel.telefone:""
  ]);
  let csv = cabecalho.join(";") + "\n";
  linhas.forEach(l => csv += l.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(";") + "\n");
  baixarArquivo("nexus-escolar-alunos.csv", csv, "text/csv;charset=utf-8;");
}

function baixarArquivo(nome, conteudo, tipo){
  const blob = new Blob([conteudo], {type:tipo});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = nome;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/* ---------------------------------------------------------
   11. BANCO DE DADOS (PostgreSQL via Neon)
--------------------------------------------------------- */
function resetarDados(){
  if(!confirm("Isso substituirá todos os dados atuais por 500 alunos fictícios novos. Deseja continuar?")) return;
  carregarDados();
  atualizarPainelBancoDados(`Base fictícia padrão restaurada em ${new Date().toLocaleString("pt-BR")}.`);
  mostrarToast(t("toast.resetado"));
  renderizarTabelaAlunos();
}

function atualizarPainelBancoDados(mensagem){
  const status = document.getElementById("status-dados");
  if(status) status.textContent = mensagem;
}

async function testarConexaoDB(){
  atualizarPainelBancoDados("Testando conexão...");
  const resultado = await NexusDB.testarConexao();
  atualizarPainelBancoDados(resultado.ok
    ? `Conectado ao PostgreSQL (Neon) com sucesso em ${new Date().toLocaleString("pt-BR")}. ${resultado.totalAlunos ?? 0} aluno(s) no banco.`
    : `Falha ao conectar: ${resultado.erro}`);
  atualizarBadgeConexao(resultado.ok);
}

async function sincronizarParaDB(){
  atualizarPainelBancoDados("Enviando dados locais para o PostgreSQL...");
  const resultados = await Promise.all([
    NexusDB.enviarAlunos(ALUNOS),
    NexusDB.enviarProfessores(PROFESSORES),
    NexusDB.enviarTurmas(TURMAS),
    NexusDB.enviarMensalidades(MENSALIDADES),
    NexusDB.enviarDespesas(DESPESAS),
    NexusDB.enviarTransacoesPdv(TRANSACOES_PDV)
  ]);
  const falhas = resultados.filter(r=>!r.ok);
  atualizarPainelBancoDados(falhas.length===0
    ? `Sincronizado com o banco em ${new Date().toLocaleString("pt-BR")}: ${ALUNOS.length} alunos, ${PROFESSORES.length} professores, ${TURMAS.length} turmas, ${MENSALIDADES.length} mensalidades, ${DESPESAS.length} despesas, ${TRANSACOES_PDV.length} transações do PDV.`
    : `Falha ao sincronizar: ${falhas.map(f=>f.erro).join(" | ")}`);
  atualizarBadgeConexao(falhas.length===0);
}

async function carregarDoDB(){
  atualizarPainelBancoDados("Carregando dados do banco...");
  const [rAlunos, rProfessores, rTurmas, rMensalidades, rDespesas, rTransacoes] = await Promise.all([
    NexusDB.buscarAlunos(), NexusDB.buscarProfessores(), NexusDB.buscarTurmas(),
    NexusDB.buscarMensalidades(), NexusDB.buscarDespesas(), NexusDB.buscarTransacoesPdv()
  ]);

  const conectado = rAlunos.ok; // se a primeira chamada respondeu, a API/banco estão de pé
  if(!conectado){
    atualizarPainelBancoDados(`Falha ao carregar: ${rAlunos.erro}`);
    atualizarBadgeConexao(false);
    return;
  }

  if(rAlunos.dados.length){
    ALUNOS = rAlunos.dados;
    ULTIMA_MATRICULA = Math.max(ULTIMA_MATRICULA, ...ALUNOS.map(a=>Number(a.matricula)||0)) + 1;
  }
  if(rProfessores.ok && rProfessores.dados.length){
    PROFESSORES = rProfessores.dados;
    ULTIMO_ID_PROFESSOR = Math.max(ULTIMO_ID_PROFESSOR, ...PROFESSORES.map(p=>p.id)) + 1;
  }
  if(rTurmas.ok && rTurmas.dados.length){
    TURMAS = rTurmas.dados;
    ULTIMO_ID_TURMA = Math.max(ULTIMO_ID_TURMA, ...TURMAS.map(tu=>tu.id)) + 1;
  }
  if(rMensalidades.ok && rMensalidades.dados.length){
    MENSALIDADES = rMensalidades.dados;
    ULTIMO_ID_MENSALIDADE = Math.max(ULTIMO_ID_MENSALIDADE, ...MENSALIDADES.map(m=>m.id)) + 1;
  }
  if(rDespesas.ok && rDespesas.dados.length){
    DESPESAS = rDespesas.dados;
    ULTIMO_ID_DESPESA = Math.max(ULTIMO_ID_DESPESA, ...DESPESAS.map(d=>d.id)) + 1;
  }
  if(rTransacoes.ok && rTransacoes.dados.length){
    TRANSACOES_PDV = rTransacoes.dados;
    CONTADOR_RECIBO = Math.max(CONTADOR_RECIBO, ...TRANSACOES_PDV.map(tr=>tr.numero)) + 1;
  }

  renderizarTabelaAlunos();
  if(typeof renderizarTabelaProfessores === "function") renderizarTabelaProfessores();
  if(typeof renderizarTabelaTurmas === "function") renderizarTabelaTurmas();
  if(typeof renderizarFinanceiro === "function") renderizarFinanceiro();
  if(!document.getElementById("view-dashboard").classList.contains("oculto")) renderizarDashboard();

  const algumDadoEncontrado = [rAlunos,rProfessores,rTurmas,rMensalidades,rDespesas,rTransacoes].some(r=>r.ok && r.dados.length);
  atualizarPainelBancoDados(algumDadoEncontrado
    ? `Dados carregados do PostgreSQL em ${new Date().toLocaleString("pt-BR")}: ${ALUNOS.length} alunos, ${PROFESSORES.length} professores, ${TURMAS.length} turmas, ${MENSALIDADES.length} mensalidades, ${DESPESAS.length} despesas, ${TRANSACOES_PDV.length} transações do PDV.`
    : "O banco está conectado, mas ainda não tem dados. Use \"Sincronizar agora\" para enviar a base local.");
  atualizarBadgeConexao(true);
}

function atualizarBadgeConexao(conectado){
  const badge = document.getElementById("badge-conexao-db");
  if(!badge) return;
  badge.textContent = conectado ? "Conectado" : "Desconectado";
  badge.classList.toggle("badge-sucesso", !!conectado);
  badge.classList.toggle("badge-perigo", !conectado);
}

/* ---------------------------------------------------------
   12. PDV — RECEBIMENTO DE MATRÍCULA
--------------------------------------------------------- */
function preencherSelectAlunosPDV(){
  const select = document.getElementById("pdv-aluno");
  const atual = select.value;
  select.innerHTML = `<option value="">—</option>` + alunosVisiveis().map(a=>`<option value="${a.id}">${a.matricula} — ${a.nome}</option>`).join("");
  if(atual) select.value = atual;
}

function atualizarCursosPDV(){
  const categoria = document.getElementById("pdv-categoria").value;
  const select = document.getElementById("pdv-curso");
  const info = CATEGORIAS[categoria];
  select.innerHTML = info.cursos.map(c=>`<option value="${c}">${c}</option>`).join("");
  atualizarValorCursoPDV();
  atualizarTurmasPDV();
}
function atualizarValorCursoPDV(){
  const curso = document.getElementById("pdv-curso").value;
  document.getElementById("pdv-valor").value = precoDoCurso(curso).toFixed(2);
  atualizarTrocoPDV();
}
function atualizarTurmasPDV(){
  const curso = document.getElementById("pdv-curso").value;
  const unidade = CURRENT_UNIDADE === "todas" ? "bhsede" : CURRENT_UNIDADE;
  const select = document.getElementById("pdv-turma");
  const disponiveis = TURMAS.filter(tu=>tu.curso===curso && tu.unidade===unidade && tu.status==="Ativa");
  select.innerHTML = `<option value="">Gerar turma automaticamente</option>` +
    disponiveis.map(tu=>{
      const vagas = turmasVagas(tu);
      return `<option value="${tu.id}" ${vagas<=0?'disabled':''}>${tu.codigo} — ${tu.turno} — ${vagas>0?vagas+' vaga(s)':'Lotada'}</option>`;
    }).join("");
}

function atualizarVisibilidadeRecebidoPDV(){
  const forma = document.getElementById("pdv-forma").value;
  const linha = document.getElementById("pdv-linha-recebido");
  linha.style.display = forma === "Dinheiro" ? "" : "none";
  if(forma !== "Dinheiro"){ document.getElementById("pdv-troco").value = moeda(0); }
  else atualizarTrocoPDV();
}

function atualizarTrocoPDV(){
  const valor = Number(document.getElementById("pdv-valor").value) || 0;
  const recebido = Number(document.getElementById("pdv-recebido").value) || 0;
  const troco = Math.max(0, recebido - valor);
  document.getElementById("pdv-troco").value = moeda(troco);
}

let CONTADOR_RECIBO = 1000;
let PENDENTE_PDV = null; // guarda os dados do formulário enquanto a simulação de pagamento roda

function finalizarMatriculaPDV(){
  const idSelecionado = document.getElementById("pdv-aluno").value;
  const novoNome = document.getElementById("pdv-novo-nome").value.trim();
  const novoNascimento = document.getElementById("pdv-novo-nascimento").value;
  const categoria = document.getElementById("pdv-categoria").value;
  const curso = document.getElementById("pdv-curso").value;
  const turmaId = document.getElementById("pdv-turma").value;
  const valor = Number(document.getElementById("pdv-valor").value) || 0;
  const forma = document.getElementById("pdv-forma").value;
  const recebido = Number(document.getElementById("pdv-recebido").value) || 0;

  if(!idSelecionado && !novoNome){
    alert(t("pdv.selecionealuno"));
    return;
  }
  if(valor <= 0){
    alert(IDIOMA_ATUAL==='en' ? "Enter a valid enrollment fee." : (IDIOMA_ATUAL==='es' ? "Ingrese un valor de matrícula válido." : "Informe um valor de matrícula válido."));
    return;
  }
  if(forma === "Dinheiro" && recebido < valor){
    alert(IDIOMA_ATUAL==='en' ? "Amount received is less than the enrollment fee." : (IDIOMA_ATUAL==='es' ? "El monto recibido es menor que el valor de la matrícula." : "O valor recebido é menor que o valor da matrícula."));
    return;
  }
  if(turmaId){
    const turmaEscolhida = TURMAS.find(tu=>tu.id===Number(turmaId));
    if(turmaEscolhida && turmasVagas(turmaEscolhida) <= 0){
      alert("Esta turma está lotada. Escolha outra turma ou gere uma turma automaticamente.");
      return;
    }
  }

  PENDENTE_PDV = { idSelecionado, novoNome, novoNascimento, categoria, curso, turmaId, valor, forma, recebido };
  abrirSimulacaoPagamento();
}

/* ---------------------------------------------------------
   SIMULAÇÃO DE PAGAMENTO (PDV) — Dinheiro / PIX / Débito / Crédito / Boleto
--------------------------------------------------------- */
function abrirSimulacaoPagamento(){
  const { valor, forma } = PENDENTE_PDV;
  document.getElementById("modal-pagamento").classList.remove("oculto");
  document.getElementById("pag-titulo").textContent =
    IDIOMA_ATUAL==='en' ? "Processing payment" : (IDIOMA_ATUAL==='es' ? "Procesando pago" : "Processando pagamento");

  if(forma === "Dinheiro") return telaPagamentoDinheiro(valor);
  if(forma === "PIX") return telaPagamentoPix(valor);
  if(forma === "Cartão de Débito" || forma === "Cartão de Crédito") return telaPagamentoCartao(valor, forma);
  if(forma === "Boleto") return telaPagamentoBoleto(valor);
}

function fecharSimulacaoPagamento(cancelarTransacao){
  document.getElementById("modal-pagamento").classList.add("oculto");
  if(cancelarTransacao) PENDENTE_PDV = null;
}

function telaPagamentoDinheiro(valor){
  const troco = Math.max(0, PENDENTE_PDV.recebido - valor);
  document.getElementById("pag-corpo").innerHTML = `
    <div class="pag-icone-ok">💵</div>
    <div class="pag-valor">${moeda(valor)}</div>
    <p class="pag-sub">${IDIOMA_ATUAL==='en'?"Cash received at the counter.":(IDIOMA_ATUAL==='es'?"Efectivo recibido en caja.":"Pagamento em espécie recebido no caixa.")}</p>
    <p class="pag-status ok">${IDIOMA_ATUAL==='en'?`Change: ${moeda(troco)}`:(IDIOMA_ATUAL==='es'?`Cambio: ${moeda(troco)}`:`Troco a devolver: ${moeda(troco)}`)}</p>
    <div class="pag-acoes">
      <button class="btn btn-outline" onclick="fecharSimulacaoPagamento(true)">${IDIOMA_ATUAL==='en'?"Cancel":(IDIOMA_ATUAL==='es'?"Cancelar":"Cancelar")}</button>
      <button class="btn btn-primario" onclick="concluirTransacaoPDV()">${IDIOMA_ATUAL==='en'?"Confirm receipt":(IDIOMA_ATUAL==='es'?"Confirmar recepción":"Confirmar recebimento")}</button>
    </div>`;
}

function telaPagamentoCartao(valor, forma){
  document.getElementById("pag-corpo").innerHTML = `
    <div class="pag-maquininha">
      <div class="pag-maquininha-tela">${forma==="Cartão de Crédito" ? "CREDITO" : "DEBITO"}<br>${moeda(valor)}</div>
      <div class="pag-cartao"></div>
      <div class="pag-maquininha-teclado">${"<div></div>".repeat(9)}</div>
    </div>
    <div class="pag-valor">${moeda(valor)}</div>
    <p class="pag-status espera" id="pag-status-cartao">${IDIOMA_ATUAL==='en'?"Insert, tap or swipe the card...":(IDIOMA_ATUAL==='es'?"Inserte, aproxime o pase la tarjeta...":"Insira, aproxime ou passe o cartão...")}</p>`;

  setTimeout(()=>{
    const statusEl = document.getElementById("pag-status-cartao");
    if(!statusEl) return; // modal foi fechado/cancelado antes
    statusEl.textContent = IDIOMA_ATUAL==='en' ? "Processing transaction..." : (IDIOMA_ATUAL==='es' ? "Procesando transacción..." : "Processando transação...");
    document.querySelector(".pag-maquininha-tela").textContent = "PROCESSANDO...";

    setTimeout(()=>{
      if(!document.getElementById("pag-status-cartao")) return;
      const aprovado = Math.random() > 0.12; // ~88% de aprovação, simula recusas ocasionais
      if(aprovado){
        document.getElementById("pag-corpo").innerHTML = `
          <div class="pag-icone-ok">✔</div>
          <div class="pag-valor">${moeda(valor)}</div>
          <p class="pag-status ok">${IDIOMA_ATUAL==='en'?"Transaction approved!":(IDIOMA_ATUAL==='es'?"¡Transacción aprobada!":"Transação aprovada!")}</p>
          <p class="pag-sub">${IDIOMA_ATUAL==='en'?"Issuing enrollment receipt...":(IDIOMA_ATUAL==='es'?"Emitiendo el recibo...":"Emitindo recibo da matrícula...")}</p>`;
        setTimeout(()=>concluirTransacaoPDV(), 900);
      } else {
        document.getElementById("pag-corpo").innerHTML = `
          <div class="pag-icone-erro">✕</div>
          <div class="pag-valor">${moeda(valor)}</div>
          <p class="pag-status erro">${IDIOMA_ATUAL==='en'?"Transaction declined by the card issuer.":(IDIOMA_ATUAL==='es'?"Transacción rechazada por el emisor.":"Transação recusada pela operadora do cartão.")}</p>
          <div class="pag-acoes">
            <button class="btn btn-outline" onclick="fecharSimulacaoPagamento(true)">${IDIOMA_ATUAL==='en'?"Cancel":(IDIOMA_ATUAL==='es'?"Cancelar":"Cancelar")}</button>
            <button class="btn btn-primario" onclick="telaPagamentoCartao(${valor}, '${forma}')">${IDIOMA_ATUAL==='en'?"Try again":(IDIOMA_ATUAL==='es'?"Intentar de nuevo":"Tentar novamente")}</button>
          </div>`;
      }
    }, 1700);
  }, 1300);
}

function gerarQRFake(){
  let quadros = "";
  for(let i=0;i<81;i++) quadros += Math.random() > 0.42 ? "<div></div>" : "<div class=\"off\"></div>";
  return quadros;
}
function gerarCodigoPixFake(valor){
  const hex = () => Math.random().toString(36).slice(2,10).toUpperCase();
  return `00020126580014BR.GOV.BCB.PIX0136${hex()}-${hex()}-${hex()}5204000053039865406${valor.toFixed(2)}5802BR5915FAC INTEGRA MAT6009SAO PAULO62070503***6304${hex().slice(0,4)}`;
}

function telaPagamentoPix(valor){
  const codigo = gerarCodigoPixFake(valor);
  document.getElementById("pag-corpo").innerHTML = `
    <div class="pag-qr">${gerarQRFake()}</div>
    <div class="pag-valor">${moeda(valor)}</div>
    <div class="pag-pix-codigo" id="pag-pix-codigo">${codigo}</div>
    <p class="pag-status espera" id="pag-status-pix">${IDIOMA_ATUAL==='en'?"Waiting for payment...":(IDIOMA_ATUAL==='es'?"Esperando el pago...":"Aguardando confirmação do pagamento...")}</p>
    <div class="pag-spinner" id="pag-spinner-pix"></div>
    <div class="pag-acoes">
      <button class="btn btn-outline" onclick="fecharSimulacaoPagamento(true)">${IDIOMA_ATUAL==='en'?"Cancel":(IDIOMA_ATUAL==='es'?"Cancelar":"Cancelar")}</button>
      <button class="btn btn-primario" onclick="confirmarPixManual()">${IDIOMA_ATUAL==='en'?"I already paid":(IDIOMA_ATUAL==='es'?"Ya pagué":"Já paguei")}</button>
    </div>`;

  // simula o recebimento automático da confirmação do PSP em alguns segundos
  const timeout = setTimeout(()=>{
    if(document.getElementById("pag-status-pix")) aprovarPixSimulado();
  }, 4500 + Math.random()*2500);
  PENDENTE_PDV.timeoutPix = timeout;
}
function confirmarPixManual(){
  if(PENDENTE_PDV && PENDENTE_PDV.timeoutPix) clearTimeout(PENDENTE_PDV.timeoutPix);
  aprovarPixSimulado();
}
function aprovarPixSimulado(){
  if(!document.getElementById("pag-status-pix")) return;
  document.getElementById("pag-corpo").innerHTML = `
    <div class="pag-icone-ok">✔</div>
    <div class="pag-valor">${moeda(PENDENTE_PDV.valor)}</div>
    <p class="pag-status ok">${IDIOMA_ATUAL==='en'?"PIX payment confirmed!":(IDIOMA_ATUAL==='es'?"¡Pago por PIX confirmado!":"Pagamento via PIX confirmado!")}</p>
    <p class="pag-sub">${IDIOMA_ATUAL==='en'?"Issuing enrollment receipt...":(IDIOMA_ATUAL==='es'?"Emitiendo el recibo...":"Emitindo recibo da matrícula...")}</p>`;
  setTimeout(()=>concluirTransacaoPDV(), 900);
}

function telaPagamentoBoleto(valor){
  const linhaDigitavel = `341${numeroEntre(10000,99999)}.${numeroEntre(10000,99999)} ${numeroEntre(10000,99999)}.${numeroEntre(100000,999999)} ${numeroEntre(10000,99999)}.${numeroEntre(100000,999999)} 1 ${String(numeroEntre(10000000000000,99999999999999))}`;
  document.getElementById("pag-corpo").innerHTML = `
    <div class="pag-boleto-barras"></div>
    <div class="pag-boleto-linha">${linhaDigitavel}</div>
    <div class="pag-valor">${moeda(valor)}</div>
    <p class="pag-status espera">${IDIOMA_ATUAL==='en'?"Bank slip generated. Awaiting bank clearance (simulation).":(IDIOMA_ATUAL==='es'?"Boleto generado. Esperando compensación bancaria (simulación).":"Boleto gerado. Aguardando compensação bancária (simulação).")}</p>
    <div class="pag-acoes">
      <button class="btn btn-outline" onclick="fecharSimulacaoPagamento(true)">${IDIOMA_ATUAL==='en'?"Cancel":(IDIOMA_ATUAL==='es'?"Cancelar":"Cancelar")}</button>
      <button class="btn btn-primario" onclick="concluirTransacaoPDV()">${IDIOMA_ATUAL==='en'?"Simulate payment confirmed":(IDIOMA_ATUAL==='es'?"Simular pago confirmado":"Simular pagamento confirmado")}</button>
    </div>`;
}

function concluirTransacaoPDV(){
  if(!PENDENTE_PDV) return;
  const { idSelecionado, novoNome, novoNascimento, categoria, curso, turmaId, valor, forma, recebido } = PENDENTE_PDV;

  const unidadeAluno = CURRENT_UNIDADE === "todas" ? "bhsede" : CURRENT_UNIDADE;
  let codigoTurma;
  const turmaEscolhida = turmaId ? TURMAS.find(tu=>tu.id===Number(turmaId)) : null;
  if(turmaEscolhida){
    codigoTurma = turmaEscolhida.codigo;
  } else {
    const hoje = new Date();
    const anoTurma = hoje.getFullYear();
    const semestreTurma = hoje.getMonth() < 6 ? 1 : 2;
    const siglaCurso = curso.split(" ").map(p=>p[0]).join("").toUpperCase().slice(0,4);
    codigoTurma = `${siglaCurso}-${anoTurma}.${semestreTurma}`;
    if(!TURMAS.find(tu=>tu.codigo===codigoTurma && tu.unidade===unidadeAluno)){
      TURMAS.push({ id: ULTIMO_ID_TURMA++, codigo:codigoTurma, curso, categoria, unidade:unidadeAluno,
        professorId:null, turno:"Noite", horario:HORARIOS_TURNO["Noite"], sala:"A definir", capacidade:9999, status:"Ativa" });
    }
  }

  let aluno;
  if(idSelecionado){
    aluno = ALUNOS.find(a=>a.id===Number(idSelecionado));
    aluno.categoria = categoria; aluno.curso = curso; aluno.turma = codigoTurma; aluno.status = "Ativo";
  } else {
    const nascimento = novoNascimento || paraInputDate(gerarDataNascimento(CATEGORIAS[categoria].idadeMin, CATEGORIAS[categoria].idadeMax));
    const idade = calcularIdade(new Date(nascimento));
    const menorIdade = idade < 18;
    const novoId = Math.max(...ALUNOS.map(a=>a.id), 0) + 1;
    const hoje = new Date();
    const infoUnidadeAluno = UNIDADES[unidadeAluno];
    aluno = {
      id: novoId, matricula: String(ULTIMA_MATRICULA++), ra: gerarRA(), nome: novoNome, genero:"M",
      nascimento, cpf: gerarCPF(), telefone: gerarTelefone(),
      email: `${novoNome.split(" ")[0].toLowerCase()}.${novoId}@aluno.etec.br`,
      endereco: `Endereço não informado - ${infoUnidadeAluno.cidade}/${infoUnidadeAluno.uf}`,
      unidade: unidadeAluno,
      categoria, curso, turma: codigoTurma,
      cargaHoraria: CATEGORIAS[categoria].cargaHoraria,
      dataMatricula: paraInputDate(hoje), status: "Ativo", menorIdade,
      responsavel: menorIdade ? { nome:"", parentesco:"", cpf:"", telefone:"" } : null
    };
    ALUNOS.push(aluno);
  }

  const transacao = {
    numero: CONTADOR_RECIBO++,
    alunoId: aluno.id, alunoNome: aluno.nome, curso, categoria, valor, forma,
    recebido: forma==="Dinheiro" ? recebido : valor,
    troco: forma==="Dinheiro" ? Math.max(0, recebido-valor) : 0,
    dataHora: new Date()
  };
  TRANSACOES_PDV.push(transacao);

  gerarReciboPDV(transacao, aluno);
  renderizarCaixaDoDia();
  if(NexusDB.estaConfigurado()){
    NexusDB.enviarAlunos([aluno]).then(()=>{}); // garante que o aluno novo/atualizado também esteja no banco
    NexusDB.enviarTransacoesPdv([transacao]).then(r=>{ if(!r.ok) mostrarToast("Aviso: não foi possível sincronizar a venda com o banco."); });
  }
  preencherSelectAlunosPDV();
  atualizarTurmasPDV();
  if(!document.getElementById("view-turmas").classList.contains("oculto")) renderizarTabelaTurmas();
  if(!document.getElementById("view-financeiro").classList.contains("oculto")) renderizarFinanceiro();
  document.getElementById("pdv-novo-nome").value = "";
  document.getElementById("pdv-novo-nascimento").value = "";
  document.getElementById("pdv-recebido").value = "";
  fecharSimulacaoPagamento(false);
  PENDENTE_PDV = null;
  mostrarToast(t("toast.matriculapaga"));
}

function renderizarCaixaDoDia(){
  const hoje = new Date().toDateString();
  const transacoesHoje = TRANSACOES_PDV.filter(tr => tr.dataHora.toDateString() === hoje);
  const total = transacoesHoje.reduce((s,tr)=>s+tr.valor,0);
  document.getElementById("pdv-total-dia").textContent = moeda(total);
  document.getElementById("pdv-qtd-dia").textContent = transacoesHoje.length;
  document.getElementById("pdv-lista-transacoes").innerHTML = [...transacoesHoje].reverse().map(tr=>`
    <tr><td>${tr.dataHora.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</td>
    <td>${tr.alunoNome}</td><td>${moeda(tr.valor)}</td><td>${tr.forma}</td></tr>
  `).join("") || `<tr><td colspan="4" style="text-align:center;color:#9aa3b8;padding:14px;">—</td></tr>`;
}

function gerarReciboPDV(transacao, aluno, containerId){
  const cont = document.getElementById(containerId || "folha-recibo");
  cont.classList.remove("oculto");
  const hoje = transacao.dataHora.toLocaleString("pt-BR");
  const infoUnidade = UNIDADES[aluno.unidade] || UNIDADES[CURRENT_UNIDADE] || UNIDADES.bhsede;
  cont.innerHTML = `<div class="folha">
    <div class="folha-cabecalho">
      <img src="${DOC_LOGO_DATA_URI}" alt="Nexus Tech University">
      <div><h1>NEXUS TECH UNIVERSIDADE</h1>
      <p>Unidade ${infoUnidade.nome} · Ensino · Pessoas · Futuro</p>
      <p class="folha-endereco-unidade">${infoUnidade.endereco}</p></div>
    </div>
    <div class="folha-titulo">${t("pdv.recibo.titulo")} — ${t("pdv.recibo.numero")} ${transacao.numero}</div>
    <p class="corpo">${t("pdv.recibo.recebemos")} <span class="destaque">${aluno.nome}</span> ${t("pdv.recibo.valorextenso")}
      <span class="destaque">${moeda(transacao.valor)}</span>, ${t("pdv.recibo.referente")} <span class="destaque">${transacao.curso}</span>
      (${t(CHAVE_CATEGORIA[transacao.categoria])}).</p>
    <table class="folha-tabela">
      <tr><th>${t("pdv.recibo.formapag")}</th><td>${transacao.forma}</td>
          <th>${t("tabela.matricula")}</th><td>${aluno.matricula}</td></tr>
      ${transacao.forma==="Dinheiro" ? `<tr><th>${t("pdv.valorrecebido")}</th><td>${moeda(transacao.recebido)}</td>
          <th>${t("pdv.troco")}</th><td>${moeda(transacao.troco)}</td></tr>` : ``}
    </table>
    <p class="corpo" style="text-align:right;">${infoUnidade.cidade}/${infoUnidade.uf}, ${hoje}.</p>
    <div class="folha-assinaturas"><div>${t("pdv.recibo.assinatura")} — ${CURRENT_USUARIO ? CURRENT_USUARIO.nome : ""}</div><div>${aluno.nome}</div></div>
    <div class="folha-rodape">Nexus Tech University — ${infoUnidade.nome}</div>
  </div>`;
}

/* ---------------------------------------------------------
   13. RELATÓRIOS
--------------------------------------------------------- */
function cabecalhoRelatorio(titulo){
  const infoUnidade = UNIDADES[CURRENT_UNIDADE] || null;
  const subtitulo = infoUnidade
    ? `Nexus Tech University — Unidade ${infoUnidade.nome} · Emitido em ${new Date().toLocaleString("pt-BR")}`
    : `Nexus Tech University — Todas as unidades · Emitido em ${new Date().toLocaleString("pt-BR")}`;
  return `<div class="rel-cabecalho">
    <img src="${DOC_LOGO_DATA_URI}" alt="Nexus Tech University">
    <div><h4>${titulo}</h4><span>${subtitulo}</span></div>
  </div>`;
}

function gerarRelatorio(tipo){
  const area = document.getElementById("area-relatorio");
  const base = alunosVisiveis();

  if(tipo === "geral"){
    area.innerHTML = cabecalhoRelatorio(t("rel.geral")) +
      `<div class="rel-resumo">
        <div><b>${base.length}</b>${t("kpi.total")}</div>
        <div><b>${base.filter(a=>a.status==="Ativo").length}</b>${t("status.ativo")}</div>
        <div><b>${base.filter(a=>a.status==="Concluído").length}</b>${t("status.concluido")}</div>
        <div><b>${base.filter(a=>a.menorIdade).length}</b>${t("kpi.menores")}</div>
      </div>` + tabelaRelatorio(base);
  }

  if(tipo === "categoria"){
    let html = cabecalhoRelatorio(t("rel.categoria"));
    NOMES_CATEGORIAS.forEach(cat=>{
      const lista = base.filter(a=>a.categoria===cat);
      html += `<h4 style="color:#0b1e4a;margin:18px 0 8px;">${t(CHAVE_CATEGORIA[cat])} <span style="font-weight:400;color:#8a93a8;font-size:12px;">(${lista.length})</span></h4>`;
      html += tabelaRelatorio(lista, true);
    });
    area.innerHTML = html;
  }

  if(tipo === "menores"){
    const lista = base.filter(a=>a.menorIdade);
    area.innerHTML = cabecalhoRelatorio(t("rel.menores")) +
      `<div class="rel-resumo"><div><b>${lista.length}</b>${t("kpi.menores")}</div></div>` +
      `<table class="folha-tabela"><thead><tr><th>${t("tabela.matricula")}</th><th>${t("tabela.aluno")}</th><th>${t("tabela.idade")}</th><th>${t("tabela.curso")}</th><th>${t("tabela.responsavel")}</th><th>${t("modal.parentesco")}</th><th>${t("modal.resptelefone")}</th></tr></thead><tbody>` +
      lista.map(a=>`<tr><td>${a.matricula}</td><td>${a.nome}</td><td>${calcularIdade(new Date(a.nascimento))}</td><td>${a.curso}</td>
        <td>${a.responsavel.nome}</td><td>${a.responsavel.parentesco}</td><td>${a.responsavel.telefone}</td></tr>`).join("") +
      `</tbody></table>`;
  }

  if(tipo === "situacao"){
    let html = cabecalhoRelatorio(t("rel.situacao"));
    STATUS_LISTA_UNICA().forEach(st=>{
      const lista = base.filter(a=>a.status===st);
      html += `<h4 style="color:#0b1e4a;margin:18px 0 8px;">${t(CHAVE_STATUS[st])} <span style="font-weight:400;color:#8a93a8;font-size:12px;">(${lista.length})</span></h4>`;
      html += tabelaRelatorio(lista, true);
    });
    area.innerHTML = html;
  }

  if(tipo === "financeiro"){
    const total = TRANSACOES_PDV.reduce((s,tr)=>s+tr.valor,0);
    const porForma = {};
    TRANSACOES_PDV.forEach(tr=> porForma[tr.forma] = (porForma[tr.forma]||0)+tr.valor );
    let html = cabecalhoRelatorio(t("rel.financeiro")) +
      `<div class="rel-resumo"><div><b>${moeda(total)}</b>${t("pdv.totalarrecadado")}</div><div><b>${TRANSACOES_PDV.length}</b>${t("pdv.qtdmatriculas")}</div></div>` +
      `<table class="folha-tabela"><thead><tr><th>${t("pdv.forma")}</th><th>${t("pdv.valor")}</th></tr></thead><tbody>` +
      Object.entries(porForma).map(([forma,v])=>`<tr><td>${forma}</td><td>${moeda(v)}</td></tr>`).join("") +
      `</tbody></table>
      <table class="folha-tabela"><thead><tr><th>${t("pdv.recibo.numero")}</th><th>${t("pdv.hora")}</th><th>${t("tabela.aluno")}</th><th>${t("tabela.curso")}</th><th>${t("pdv.valor")}</th><th>${t("pdv.forma")}</th></tr></thead><tbody>` +
      TRANSACOES_PDV.map(tr=>`<tr><td>${tr.numero}</td><td>${tr.dataHora.toLocaleString("pt-BR")}</td><td>${tr.alunoNome}</td><td>${tr.curso}</td><td>${moeda(tr.valor)}</td><td>${tr.forma}</td></tr>`).join("") +
      `</tbody></table>`;
    if(TRANSACOES_PDV.length===0) html += `<p class="texto-info">${IDIOMA_ATUAL==='en'?'No payments recorded in this session yet.':(IDIOMA_ATUAL==='es'?'Aún no hay pagos registrados en esta sesión.':'Ainda não há pagamentos registrados nesta sessão.')}</p>`;
    area.innerHTML = html;
  }
}

function tabelaRelatorio(lista, compacta){
  return `<table class="folha-tabela"><thead><tr>
      <th>${t("tabela.matricula")}</th><th>${t("tabela.nome")}</th><th>${t("tabela.idade")}</th>${compacta?"":`<th>${t("tabela.categoria")}</th>`}<th>${t("tabela.curso")}</th><th>${t("tabela.turma")}</th><th>${t("tabela.situacao")}</th>
    </tr></thead><tbody>` +
    lista.map(a=>`<tr><td>${a.matricula}</td><td>${a.nome}</td><td>${calcularIdade(new Date(a.nascimento))}</td>
      ${compacta?"":`<td>${t(CHAVE_CATEGORIA[a.categoria])}</td>`}<td>${a.curso}</td><td>${a.turma}</td><td>${t(CHAVE_STATUS[a.status])}</td></tr>`).join("") +
    `</tbody></table>`;
}

