function preencherSelectAlunos(){
  const select = document.getElementById("doc-aluno");
  const atual = select.value;
  const ehAluno = CURRENT_USUARIO && CURRENT_USUARIO.perfil === "Aluno";
  const lista = ehAluno ? ALUNOS.filter(a=>a.id === CURRENT_USUARIO.vinculoId) : alunosVisiveis();
  select.innerHTML = lista.map(a=>`<option value="${a.id}">${a.matricula} — ${a.nome}</option>`).join("");
  select.disabled = ehAluno;
  if(atual) select.value = atual;
  if(ehAluno && lista[0]) select.value = lista[0].id;
}

