/* ---------------------------------------------------------
   15. LOGIN / LOGOUT
--------------------------------------------------------- */
/* Controle simples de tentativas inválidas por sessão (bloqueio temporário, estilo corporativo) */
let TENTATIVAS_LOGIN_INVALIDAS = 0;
const LIMITE_TENTATIVAS_LOGIN = 5;
let LOGIN_BLOQUEADO_ATE = 0;

function tentarLogin(ev){
  ev.preventDefault();
  const usuario = document.getElementById("login-usuario").value.trim();
  const senha = document.getElementById("login-senha").value.trim();
  const erro = document.getElementById("login-erro");
  const btnEntrar = document.getElementById("btn-entrar-login");

  if(Date.now() < LOGIN_BLOQUEADO_ATE){
    const segundosRestantes = Math.ceil((LOGIN_BLOQUEADO_ATE - Date.now()) / 1000);
    erro.textContent = t("login.erro.bloqueado").replace("{s}", segundosRestantes);
    erro.classList.remove("oculto");
    return;
  }

  if(!usuario || !senha){
    erro.textContent = t("login.erro");
    erro.classList.remove("oculto");
    return;
  }

  const conta = buscarUsuario(usuario, senha);

  if(!conta){
    TENTATIVAS_LOGIN_INVALIDAS++;
    if(TENTATIVAS_LOGIN_INVALIDAS >= LIMITE_TENTATIVAS_LOGIN){
      LOGIN_BLOQUEADO_ATE = Date.now() + 30000;
      TENTATIVAS_LOGIN_INVALIDAS = 0;
      erro.textContent = t("login.erro.bloqueado").replace("{s}", 30);
    } else {
      erro.textContent = t("login.erro.invalido");
    }
    erro.classList.remove("oculto");
    return;
  }

  TENTATIVAS_LOGIN_INVALIDAS = 0;
  erro.classList.add("oculto");

  // Pequeno feedback de carregamento, como em sistemas corporativos
  if(btnEntrar){
    btnEntrar.disabled = true;
    btnEntrar.classList.add("btn-carregando");
  }

  setTimeout(() => {
    CURRENT_USUARIO = conta;
    // Diretoria/Super Admin (unidade "todas") sempre entram enxergando todas as
    // unidades por padrão — o seletor no topo do painel permite focar em uma só depois.
    CURRENT_UNIDADE = conta.unidade === "todas" ? "todas" : conta.unidade;

    registrarAcesso(conta, CURRENT_UNIDADE);
    aplicarUsuarioNaInterface();

    document.getElementById("tela-login").classList.add("oculto");
    document.getElementById("app").classList.remove("oculto");
    document.getElementById("ia-botao-flutuante").classList.remove("oculto");
    window.scrollTo(0, 0);
    irParaView(conta.perfil === "Aluno" ? "portal-aluno" : (conta.perfil === "Professor" ? "portal-professor" : "dashboard"));
    iniciarTempoReal();

    if(btnEntrar){
      btnEntrar.disabled = false;
      btnEntrar.classList.remove("btn-carregando");
    }
  }, 350);
}

/* Log simples de acessos (fica em memória; item 1 do roadmap de segurança) */
let LOG_ACESSOS = [];
function detectarDispositivo(){
  const ua = navigator.userAgent || "";
  let nav = "Navegador";
  if(/Edg\//.test(ua)) nav = "Edge";
  else if(/Chrome\//.test(ua) && !/Chromium/.test(ua)) nav = "Chrome";
  else if(/Firefox\//.test(ua)) nav = "Firefox";
  else if(/Safari\//.test(ua) && !/Chrome/.test(ua)) nav = "Safari";
  let so = "";
  if(/Windows/.test(ua)) so = "Windows";
  else if(/Mac OS X/.test(ua)) so = "macOS";
  else if(/Android/.test(ua)) so = "Android";
  else if(/iPhone|iPad/.test(ua)) so = "iOS";
  else if(/Linux/.test(ua)) so = "Linux";
  return so ? `${nav} · ${so}` : nav;
}
function registrarAcesso(conta, unidade){
  // Encerra a sessão "ativa" anterior deste mesmo usuário (nesta memória local)
  LOG_ACESSOS.filter(s=>s.usuario===conta.usuario && s.status==="Ativa").forEach(s=>s.status="Encerrada");
  LOG_ACESSOS.unshift({
    id: "S" + Date.now().toString(36).toUpperCase(),
    usuario: conta.usuario,
    nome: conta.nome,
    perfil: conta.perfil,
    unidade,
    dispositivo: detectarDispositivo(),
    data: new Date().toISOString(),
    status: "Ativa"
  });
  if(LOG_ACESSOS.length > 200) LOG_ACESSOS.length = 200;
  registrarAuditoria("Login", "Segurança", `${conta.nome} entrou no sistema (${UNIDADES[unidade]?UNIDADES[unidade].nome:unidade}).`);
}

/* Log de auditoria de ações — criação/edição/exclusão de registros pelos usuários */
let LOG_AUDITORIA = [];
function registrarAuditoria(acao, modulo, detalhe){
  LOG_AUDITORIA.unshift({
    data: new Date().toISOString(),
    usuario: CURRENT_USUARIO ? CURRENT_USUARIO.nome : "—",
    perfil: CURRENT_USUARIO ? CURRENT_USUARIO.perfil : "—",
    acao, modulo, detalhe: detalhe || ""
  });
  if(LOG_AUDITORIA.length > 500) LOG_AUDITORIA.length = 500;
}

function renderizarAuditoria(){
  const busca = (document.getElementById("auditoria-busca").value || "").toLowerCase();
  const filtroAcao = document.getElementById("auditoria-filtro-acao").value;
  const linhas = LOG_AUDITORIA
    .filter(l => !filtroAcao || l.acao === filtroAcao)
    .filter(l => !busca || `${l.usuario} ${l.modulo} ${l.acao} ${l.detalhe}`.toLowerCase().includes(busca))
    .slice(0, 200)
    .map(l => `<tr>
        <td>${new Date(l.data).toLocaleString("pt-BR")}</td>
        <td>${l.usuario}</td>
        <td>${l.perfil}</td>
        <td><span class="badge-acao badge-acao-${l.acao}">${l.acao}</span></td>
        <td>${l.modulo}</td>
        <td>${l.detalhe}</td>
      </tr>`).join("");
  document.getElementById("auditoria-tbody").innerHTML = linhas ||
    `<tr><td colspan="6" style="text-align:center;padding:24px;color:#9aa3b8;">Nenhuma ação registrada ainda nesta sessão.</td></tr>`;
}

function renderizarSessoes(){
  const linhas = LOG_ACESSOS.slice(0, 100).map(s => {
    const ehSessaoAtual = CURRENT_USUARIO && s.usuario === CURRENT_USUARIO.usuario && s.status === "Ativa";
    return `<tr>
        <td>${s.nome}${ehSessaoAtual?` <span class="chip-sessao-atual">${t("sessoes.estasessao")}</span>`:""}</td>
        <td>${s.unidade==="todas"?"Todas":(UNIDADES[s.unidade]?UNIDADES[s.unidade].nome:s.unidade)}</td>
        <td>${s.dispositivo||"—"}</td>
        <td>${new Date(s.data).toLocaleString("pt-BR")}</td>
        <td><span class="badge-sessao badge-sessao-${s.status==="Ativa"?"ativa":"encerrada"}">${s.status}</span></td>
        <td>${s.status==="Ativa" ? `<button type="button" class="link-editar" onclick="encerrarSessao('${s.id}')">${t("sessoes.encerrar")}</button>` : ""}</td>
      </tr>`;
  }).join("");
  document.getElementById("sessoes-tbody").innerHTML = linhas ||
    `<tr><td colspan="6" style="text-align:center;padding:24px;color:#9aa3b8;">Nenhuma sessão registrada ainda.</td></tr>`;
}

function encerrarSessao(id){
  const sessao = LOG_ACESSOS.find(s=>s.id===id);
  if(!sessao) return;
  const ehMinhaPropriaSessao = CURRENT_USUARIO && sessao.usuario === CURRENT_USUARIO.usuario && sessao.status === "Ativa";
  sessao.status = "Encerrada";
  registrarAuditoria("Login", "Segurança", `Sessão de ${sessao.nome} encerrada manualmente.`);
  renderizarSessoes();
  if(ehMinhaPropriaSessao){
    mostrarToast(t("sessoes.suasessaoencerrada"));
    sairDoSistema();
  } else {
    mostrarToast(t("sessoes.encerradasucesso"));
  }
}

function aplicarUsuarioNaInterface(){
  const nomeTopo = document.getElementById("usuario-nome-topo");
  const perfilTopo = document.getElementById("usuario-perfil-topo");
  const avatar = document.getElementById("avatar-mini");
  const chipUnidade = document.getElementById("chip-unidade");
  const sidebarUnidade = document.getElementById("sidebar-unidade");
  const seletorUnidade = document.getElementById("seletor-unidade");
  const nomeSidebar = document.getElementById("usuario-nome-sidebar");
  const avatarSidebar = document.getElementById("avatar-mini-sidebar");
  const unidadeNomeSidebar = document.getElementById("sidebar-unidade-nome");

  nomeTopo.textContent = CURRENT_USUARIO.nome;
  perfilTopo.textContent = CURRENT_USUARIO.perfil;
  avatar.textContent = CURRENT_USUARIO.nome.split(" ").map(p=>p[0]).slice(0,2).join("").toUpperCase();
  if(nomeSidebar) nomeSidebar.textContent = CURRENT_USUARIO.nome;
  if(avatarSidebar) avatarSidebar.textContent = avatar.textContent;

  const podeAlternarUnidade = CURRENT_USUARIO.unidade === "todas";
  seletorUnidade.classList.toggle("oculto", !podeAlternarUnidade);
  if(podeAlternarUnidade) seletorUnidade.value = CURRENT_UNIDADE;

  const infoUnidade = UNIDADES[CURRENT_UNIDADE];
  const nomeUnidadeAtual = infoUnidade ? infoUnidade.nome : t("login.todasunidades");
  chipUnidade.textContent = nomeUnidadeAtual;
  sidebarUnidade.textContent = nomeUnidadeAtual;
  if(unidadeNomeSidebar) unidadeNomeSidebar.textContent = nomeUnidadeAtual;

  aplicarPermissoesPerfil();
}

/* ---------------------------------------------------------
   PERMISSÕES POR FUNÇÃO — restringe o menu lateral de acordo
   com o perfil da conta autenticada.
   null = acesso completo a todos os grupos do menu.
--------------------------------------------------------- */
const GRUPOS_POR_PERFIL_PADRAO = {
  Admin: null,
  Diretoria: null,
  Secretaria: ["academico","secretaria","comunicacao","relatorios"],
  Financeiro: ["financeiro","relatorios"],
  Professor: ["academico","comunicacao","portais"],
  Aluno: ["secretaria","portais"]
};
let GRUPOS_POR_PERFIL = JSON.parse(JSON.stringify(GRUPOS_POR_PERFIL_PADRAO));

/* Perfis com acesso total fixo (não aparecem como linhas editáveis na matriz) */
const PERFIS_ACESSO_TOTAL_FIXO = ["Admin","Diretoria"];

/* Todos os grupos de menu existentes na barra lateral, na ordem em que aparecem */
const GRUPOS_MENU_INFO = [
  { chave:"academico",     nome:"Gestão Acadêmica" },
  { chave:"portais",       nome:"Portais" },
  { chave:"secretaria",    nome:"Secretaria" },
  { chave:"financeiro",    nome:"Financeiro" },
  { chave:"comunicacao",   nome:"Comunicação" },
  { chave:"relatorios",    nome:"Relatórios e BI" },
  { chave:"multiunidade",  nome:"Multiunidade" },
  { chave:"administracao", nome:"Configurações" }
];

function carregarPermissoesSalvas(){
  try{
    const salvo = localStorage.getItem("nexus_permissoes_perfil");
    if(salvo){
      const dados = JSON.parse(salvo);
      Object.keys(dados).forEach(perfil=>{
        if(GRUPOS_POR_PERFIL.hasOwnProperty(perfil) && !PERFIS_ACESSO_TOTAL_FIXO.includes(perfil)){
          GRUPOS_POR_PERFIL[perfil] = dados[perfil];
        }
      });
    }
  }catch(e){}
}
function salvarPermissoes(){
  try{
    const paraSalvar = {};
    Object.keys(GRUPOS_POR_PERFIL).forEach(perfil=>{
      if(!PERFIS_ACESSO_TOTAL_FIXO.includes(perfil)) paraSalvar[perfil] = GRUPOS_POR_PERFIL[perfil];
    });
    localStorage.setItem("nexus_permissoes_perfil", JSON.stringify(paraSalvar));
  }catch(e){}
}

function renderizarMatrizPermissoes(){
  const perfisEditaveis = Object.keys(GRUPOS_POR_PERFIL).filter(p=>!PERFIS_ACESSO_TOTAL_FIXO.includes(p));

  document.getElementById("perm-thead").innerHTML =
    `<th>Perfil</th>` + GRUPOS_MENU_INFO.map(g=>`<th title="${g.nome}">${g.nome}</th>`).join("");

  document.getElementById("perm-tbody").innerHTML = perfisEditaveis.map(perfil=>{
    const permitidos = GRUPOS_POR_PERFIL[perfil] || [];
    const celulas = GRUPOS_MENU_INFO.map(g=>{
      const marcado = permitidos.includes(g.chave);
      return `<td style="text-align:center;"><input type="checkbox" class="perm-checkbox" data-perfil="${perfil}" data-grupo="${g.chave}" ${marcado?"checked":""}></td>`;
    }).join("");
    return `<tr><td><b>${perfil}</b></td>${celulas}</tr>`;
  }).join("") + `
    <tr class="perm-linha-fixa"><td><b>Admin / Diretoria</b></td><td colspan="${GRUPOS_MENU_INFO.length}" style="color:#5b6472;">Acesso total a todas as áreas — não pode ser restringido.</td></tr>`;

  document.getElementById("perm-status").textContent = "";
}

function aoAlterarPermissao(checkbox){
  const perfil = checkbox.dataset.perfil;
  const grupo = checkbox.dataset.grupo;
  if(!GRUPOS_POR_PERFIL[perfil]) GRUPOS_POR_PERFIL[perfil] = [];
  const lista = GRUPOS_POR_PERFIL[perfil];
  const idx = lista.indexOf(grupo);
  if(checkbox.checked){
    if(idx === -1) lista.push(grupo);
  } else {
    if(idx !== -1) lista.splice(idx, 1);
  }
  salvarPermissoes();
  if(CURRENT_USUARIO && CURRENT_USUARIO.perfil === perfil) aplicarPermissoesPerfil();
  const status = document.getElementById("perm-status");
  if(status){
    status.textContent = "Alterações salvas.";
    setTimeout(()=>{ if(status.textContent === "Alterações salvas.") status.textContent = ""; }, 2000);
  }
}

function restaurarPermissoesPadrao(){
  GRUPOS_POR_PERFIL = JSON.parse(JSON.stringify(GRUPOS_POR_PERFIL_PADRAO));
  try{ localStorage.removeItem("nexus_permissoes_perfil"); }catch(e){}
  renderizarMatrizPermissoes();
  if(CURRENT_USUARIO) aplicarPermissoesPerfil();
  mostrarToast("Permissões restauradas ao padrão.");
}

function aplicarPermissoesPerfil(){
  const perfil = CURRENT_USUARIO.perfil;
  const gruposPermitidos = GRUPOS_POR_PERFIL[perfil];

  document.querySelectorAll(".nav-grupo").forEach(grupo=>{
    const permitido = !gruposPermitidos || gruposPermitidos.includes(grupo.dataset.grupo);
    grupo.classList.toggle("oculto", !permitido);
  });

  // Perfil Aluno: dentro do grupo "Secretaria" (mantido apenas para acesso a
  // Documentos), oculta os itens administrativos e deixa só a emissão de documentos.
  const ehAluno = perfil === "Aluno";
  document.querySelectorAll('.nav-grupo[data-grupo="secretaria"] .nav-item').forEach(btn=>{
    btn.classList.toggle("oculto", ehAluno && btn.dataset.view !== "documentos");
  });

  // Alunos e Professores não acessam o painel Principal (indicadores da instituição).
  const btnPrincipal = document.querySelector('.nav-item[data-view="dashboard"]');
  if(btnPrincipal) btnPrincipal.classList.toggle("oculto", ehAluno);

  // Dentro do grupo "Portais", cada perfil só vê o portal que lhe cabe.
  const ehProfessor = perfil === "Professor";
  document.querySelectorAll('.nav-grupo[data-grupo="portais"] .nav-item').forEach(btn=>{
    if(btn.dataset.view === "portal-aluno") btn.classList.toggle("oculto", ehProfessor);
    if(btn.dataset.view === "portal-professor") btn.classList.toggle("oculto", ehAluno);
  });
}

function alternarUnidade(novaUnidade){
  if(novaUnidade !== "todas" && !UNIDADES[novaUnidade]) return;
  CURRENT_UNIDADE = novaUnidade;
  aplicarUsuarioNaInterface();
  const viewAtiva = document.querySelector(".nav-item.ativo");
  if(viewAtiva) irParaView(viewAtiva.dataset.view);
}

function sairDoSistema(){
  document.getElementById("app").classList.add("oculto");
  document.getElementById("tela-login").classList.remove("oculto");
  document.getElementById("login-senha").value = "";
  document.getElementById("login-usuario").value = "";
  CURRENT_USUARIO = null;
  pararTempoReal();
}

/* ---------------------------------------------------------
   MODO ESCURO
--------------------------------------------------------- */
let TEMA_ESCURO = false;

const SVG_LUA = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8z"/></svg>';
const SVG_SOL = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M2 12h2M20 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/></svg>';
function aplicarTema(ativarEscuro, persistir){
  TEMA_ESCURO = ativarEscuro;
  document.body.classList.toggle("tema-escuro", TEMA_ESCURO);
  const iconeSvg = TEMA_ESCURO ? SVG_SOL : SVG_LUA;
  const iconeLogin = document.getElementById("icone-tema-login");
  const btnApp = document.getElementById("btn-tema-app");
  if(iconeLogin) iconeLogin.innerHTML = iconeSvg;
  if(btnApp) btnApp.innerHTML = iconeSvg;
  if(persistir !== false){
    try{ localStorage.setItem("nexus_tema_escuro", TEMA_ESCURO ? "1" : "0"); }catch(e){}
  }
}
function alternarTema(){
  aplicarTema(!TEMA_ESCURO);
}
function restaurarTemaSalvo(){
  let salvo = null;
  try{ salvo = localStorage.getItem("nexus_tema_escuro"); }catch(e){}
  if(salvo === "1") aplicarTema(true, false);
}

let LOGIN_FONTE_PASSO = 0;
function ajustarFonteLogin(delta){
  LOGIN_FONTE_PASSO = Math.max(-2, Math.min(4, LOGIN_FONTE_PASSO + delta));
  const tela = document.getElementById("tela-login");
  tela.style.fontSize = (16 + LOGIN_FONTE_PASSO * 1.5) + "px";
}

/* ---------------------------------------------------------
   MENU LATERAL RECOLHÍVEL / GAVETA NO MOBILE
--------------------------------------------------------- */
let MENU_RECOLHIDO = false;
const MEDIA_MENU_MOBILE = window.matchMedia("(max-width:760px)");

function menuEhMobile(){
  return MEDIA_MENU_MOBILE.matches;
}

function aplicarMenuRecolhido(recolhido){
  MENU_RECOLHIDO = recolhido;
  const sidebar = document.getElementById("sidebar");
  const btnAbrir = document.getElementById("btn-abrir-menu");
  const iconeRecolher = document.getElementById("icone-recolher");
  const backdrop = document.getElementById("sidebar-backdrop");
  if(sidebar) sidebar.classList.toggle("recolhida", MENU_RECOLHIDO);
  if(iconeRecolher) iconeRecolher.textContent = MENU_RECOLHIDO ? "»" : "«";
  if(btnAbrir) btnAbrir.classList.toggle("oculto", !MENU_RECOLHIDO);
  // No mobile, "recolhida" = gaveta fechada. Quando aberta, mostra o fundo escurecido
  // atrás do menu para indicar que é uma camada por cima do conteúdo.
  if(backdrop) backdrop.classList.toggle("oculto", !(menuEhMobile() && !MENU_RECOLHIDO));
  // Preferência de menu recolhido só faz sentido persistir no modo desktop
  // (ícones apenas); no mobile a gaveta sempre começa fechada.
  if(!menuEhMobile()){
    try{ localStorage.setItem("eloAcademicoMenuRecolhido", MENU_RECOLHIDO ? "1" : "0"); }catch(e){}
  }
}
function alternarMenuRecolhido(){
  aplicarMenuRecolhido(!MENU_RECOLHIDO);
}
function fecharMenuSeMobile(){
  if(menuEhMobile() && !MENU_RECOLHIDO) aplicarMenuRecolhido(true);
}
function estadoInicialMenuRecolhido(){
  if(menuEhMobile()) return true; // gaveta começa fechada no celular
  try{
    const salvo = localStorage.getItem("eloAcademicoMenuRecolhido");
    if(salvo !== null) return salvo === "1";
  }catch(e){}
  return false;
}

