/* ---------------------------------------------------------
   15b. PWA — SERVICE WORKER E INSTALAÇÃO DO APP
--------------------------------------------------------- */
let PROMPT_INSTALACAO_PWA = null;

function registrarServiceWorker(){
  if(!("serviceWorker" in navigator)) return;
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("./service-worker.js").catch(() => {
      // Ambiente sem suporte (ex.: abrindo o arquivo direto do disco) — ignora silenciosamente.
    });
  });
  // Quando uma nova versão do service worker assume o controle (após uma atualização
  // do sistema), recarrega a página uma única vez para garantir que o usuário sempre
  // veja a versão mais recente, em vez de ficar preso numa versão antiga em cache.
  let jaRecarregou = false;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if(jaRecarregou) return;
    jaRecarregou = true;
    window.location.reload();
  });
}

function configurarInstalacaoPWA(){
  const btnInstalar = document.getElementById("btn-instalar-app");
  if(!btnInstalar) return;

  // Já rodando como app instalado (standalone) — não faz sentido oferecer instalação.
  const jaInstalado = window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
  if(jaInstalado){
    btnInstalar.classList.add("oculto");
    return;
  }

  window.addEventListener("beforeinstallprompt", (evento) => {
    evento.preventDefault();
    PROMPT_INSTALACAO_PWA = evento;
    btnInstalar.classList.remove("oculto");
  });

  btnInstalar.addEventListener("click", async () => {
    if(!PROMPT_INSTALACAO_PWA) return;
    btnInstalar.disabled = true;
    PROMPT_INSTALACAO_PWA.prompt();
    try{
      await PROMPT_INSTALACAO_PWA.userChoice;
    } finally {
      PROMPT_INSTALACAO_PWA = null;
      btnInstalar.disabled = false;
      btnInstalar.classList.add("oculto");
    }
  });

  window.addEventListener("appinstalled", () => {
    btnInstalar.classList.add("oculto");
    PROMPT_INSTALACAO_PWA = null;
  });
}

/* ---------------------------------------------------------
   ASSISTENTE NEXUS — chatbot local por palavras-chave.
   100% no navegador, sem API paga nem servidor: procura por
   termos conhecidos na mensagem do usuário e responde com um
   texto pré-definido sobre o próprio sistema. Além das respostas
   fixas, ele também entende perguntas sobre números reais do
   sistema (quantos alunos, receita do mês etc.) consultando os
   dados carregados em memória — sem chamar nenhuma API externa.
--------------------------------------------------------- */
function respostaDadosDoSistemaIA(texto){
  const alunosVisiveis = () => CURRENT_UNIDADE === "todas" ? ALUNOS : ALUNOS.filter(a=>a.unidade===CURRENT_UNIDADE);
  const contemTudo = (...termos) => termos.every(t => texto.includes(t));
  const contemAlgum = (...termos) => termos.some(t => texto.includes(t));

  const perguntaQuantidade = contemAlgum("quantos","quantas","numero de","número de","total de","qtd de");

  if(perguntaQuantidade && contemAlgum("aluno","alunos","matriculado")){
    const lista = alunosVisiveis();
    const ativos = lista.filter(a=>a.status==="Ativo").length;
    return `Atualmente há ${lista.length} alunos cadastrados${CURRENT_UNIDADE!=="todas" ? " nesta unidade" : ""}, sendo ${ativos} com matrícula ativa.`;
  }
  if(perguntaQuantidade && contemAlgum("professor","professores")){
    return `Há ${PROFESSORES.length} professores cadastrados no sistema.`;
  }
  if(perguntaQuantidade && contemAlgum("turma","turmas")){
    const ativas = TURMAS.filter(t=>t.status!=="Encerrada").length;
    return `O sistema tem ${TURMAS.length} turmas cadastradas, ${ativas} delas ativas.`;
  }
  if(contemAlgum("receita do mes","receita do mês","faturamento do mes","faturamento do mês","quanto entrou","quanto recebemos") ){
    return `A receita deste mês${CURRENT_UNIDADE!=="todas" ? " (unidade atual)" : ""} está em ${moeda(totalReceitasMes())} até agora.`;
  }
  if(contemAlgum("despesa do mes","despesa do mês","despesas do mes","despesas do mês","quanto gastamos")){
    return `As despesas registradas neste mês${CURRENT_UNIDADE!=="todas" ? " (unidade atual)" : ""} somam ${moeda(totalDespesasMes())}.`;
  }
  if(contemAlgum("inadimplencia","inadimplência","inadimplentes","em atraso","atrasadas")){
    const valor = totalInadimplencia();
    const qtd = mensalidadesVisiveis().filter(m=>m.status==="Atrasada").length;
    return `A inadimplência atual${CURRENT_UNIDADE!=="todas" ? " (unidade atual)" : ""} é de ${moeda(valor)}, em ${qtd} mensalidade(s) em atraso.`;
  }
  if(contemTudo("meu","perfil") || contemAlgum("quem sou eu","minha conta")){
    if(CURRENT_USUARIO) return `Você está logado(a) como ${CURRENT_USUARIO.nome}, perfil ${CURRENT_USUARIO.perfil}, na unidade ${CURRENT_UNIDADE==="todas" ? "Todas as unidades" : ((UNIDADES[CURRENT_UNIDADE]||{}).nome || CURRENT_UNIDADE)}.`;
  }
  return null;
}

