  if(btnPermRestaurar) btnPermRestaurar.addEventListener("click", restaurarPermissoesPadrao);

  // Modo escuro
  document.getElementById("btn-tema-login").addEventListener("click", alternarTema);
  document.getElementById("btn-tema-app").addEventListener("click", alternarTema);

  // Menu lateral recolhível / gaveta no mobile
  aplicarMenuRecolhido(estadoInicialMenuRecolhido());
