  if(backdropMenu) backdropMenu.addEventListener("click", () => aplicarMenuRecolhido(true));
  document.addEventListener("keydown", (e) => {
    if(e.key === "Escape" && menuEhMobile() && !MENU_RECOLHIDO) aplicarMenuRecolhido(true);
  });
