  MEDIA_MENU_MOBILE.addEventListener("change", () => aplicarMenuRecolhido(estadoInicialMenuRecolhido()));

  // Login: mostrar/ocultar senha, cancelar, esqueceu a senha
  document.getElementById("btn-mostrar-senha").addEventListener("click", alternarVisibilidadeSenha);
