  // Relatórios
  document.querySelectorAll(".card-relatorio").forEach(card=>{
    card.addEventListener("click", () => gerarRelatorio(card.dataset.relatorio));
  });

  // Documentos
  document.getElementById("btn-gerar-doc").addEventListener("click", gerarDocumento);
